window.EXERCISES = [{"id":"worlds-greatest-stretch","name":"World's Greatest Stretch","tags":["prep","mobility","hips","hams","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"3/s","cues":["Long lunge, back knee off the floor","Elbow to instep, then rotate and reach to the ceiling","Slow and controlled — breathe into each position"],"steps":["This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.","After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side."],"muscles":["hamstrings","calves","glutes","quadriceps"],"img":["img/ex/worlds-greatest-stretch-0.jpg","img/ex/worlds-greatest-stretch-1.jpg"]},{"id":"inchworm","name":"Inchworm","tags":["prep","mobility","hams","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"6","cues":["Walk hands out to a plank, keep legs as straight as you can","Brief push-up position, then walk feet to hands","Squeeze glutes in the plank"],"steps":["Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.","Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.","Keep going until your body is parallel to the ground in a pushup position.","Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.","Continue walking until your feet are by hour hands, keeping your legs straight as you do so."],"muscles":["hamstrings"],"img":["img/ex/inchworm-0.jpg","img/ex/inchworm-1.jpg"]},{"id":"cat-cow","name":"Cat–Cow","tags":["prep","mobility","back","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"8","cues":["Hands under shoulders, knees under hips","Round up segment by segment, then arch and look forward","Move with your breath"],"steps":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."],"muscles":["lower back","middle back","traps"],"img":["img/ex/cat-cow-0.jpg","img/ex/cat-cow-1.jpg"]},{"id":"arm-circles","name":"Arm Circles","tags":["prep","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Start small, build to big circles","Both directions","Keep ribs down, don't arch"],"steps":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"muscles":["shoulders","traps"],"img":["img/ex/arm-circles-0.jpg","img/ex/arm-circles-1.jpg"]},{"id":"standing-hip-circles","name":"Standing Hip Circles","tags":["prep","mobility","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"6/s","cues":["Hold something for balance","Knee up, open out to the side, then down","Make the circle as big as you can control"],"steps":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"muscles":["abductors","adductors"],"img":["img/ex/standing-hip-circles-0.jpg","img/ex/standing-hip-circles-1.jpg"]},{"id":"leg-swings-front-back","name":"Leg Swings — Front/Back","tags":["prep","hams","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"10/s","cues":["Hold a wall, stand tall","Swing from the hip, gradually increase range","Keep the standing leg straight"],"steps":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."],"muscles":["hamstrings"],"img":["img/ex/leg-swings-front-back-0.jpg","img/ex/leg-swings-front-back-1.jpg"]},{"id":"leg-swings-side-to-side","name":"Leg Swings — Side to Side","tags":["prep","groin","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"10/s","cues":["Face a wall, hands on it","Swing across the body and out","Keep the hips square"],"steps":["Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.","Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.","Repeat this swinging motion 5-10 times, increasing the range of motion as you do so."],"muscles":["adductors"],"img":["img/ex/leg-swings-side-to-side-0.jpg","img/ex/leg-swings-side-to-side-1.jpg"]},{"id":"groiners","name":"Groiners","tags":["prep","mobility","groin","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"5/s","cues":["From a push-up position, step foot outside the hand","Sink the hips, hold a beat","Alternate sides with control"],"steps":["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."],"muscles":["adductors"],"img":["img/ex/groiners-0.jpg","img/ex/groiners-1.jpg"]},{"id":"ankle-circles","name":"Ankle Circles","tags":["prep","ankles"],"eq":["bw"],"req":[],"tier":1,"dose":"10/s","cues":["Draw big slow circles with the toes","Both directions","Good before any jumping"],"steps":["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."],"muscles":["calves"],"img":["img/ex/ankle-circles-0.jpg","img/ex/ankle-circles-1.jpg"]},{"id":"dynamic-chest-opener","name":"Dynamic Chest Opener","tags":["prep","chest","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Arms out wide, squeeze shoulder blades together","Hug yourself, then open again","Rhythmic, not forced"],"steps":["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."],"muscles":["chest","middle back"],"img":["img/ex/dynamic-chest-opener-0.jpg","img/ex/dynamic-chest-opener-1.jpg"]},{"id":"iron-cross","name":"Iron Cross","tags":["mobility","prep","hips","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"5/s","cues":["Lie on back, arms out in a T","Swing one leg across to the opposite hand","Keep both shoulders on the floor"],"steps":["Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.","To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.","Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions."],"muscles":["quadriceps"],"img":["img/ex/iron-cross-0.jpg","img/ex/iron-cross-1.jpg"]},{"id":"toe-touch-windmills","name":"Toe-Touch Windmills","tags":["prep","hams","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"8/s","cues":["Wide stance, arms out","Rotate and reach hand to opposite foot","Other arm reaches to the sky"],"steps":["Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."],"muscles":["abductors","glutes","hamstrings","lower back"],"img":["img/ex/toe-touch-windmills-0.jpg","img/ex/toe-touch-windmills-1.jpg"]},{"id":"kettlebell-halo","name":"Kettlebell Halo","tags":["prep","mobility","shoulders","tspine","lmob"],"eq":["kb","db"],"req":[],"tier":1,"dose":"5/s","cues":["Hold the bell by the horns, upside down","Circle it tight around your head","Squeeze glutes and abs so the low back doesn't arch"],"steps":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.","Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight."],"muscles":["shoulders","traps","middle back","abdominals","triceps"],"img":[]},{"id":"band-pull-apart","name":"Band Pull-Apart","tags":["prep","prehab","hpull","shoulders"],"eq":["band"],"req":[],"tier":1,"dose":"15","cues":["Arms straight at shoulder height","Pull the band to your chest by squeezing shoulder blades","Slow on the way back"],"steps":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"muscles":["shoulders","middle back","traps"],"img":["img/ex/band-pull-apart-0.jpg","img/ex/band-pull-apart-1.jpg"]},{"id":"skips","name":"Skips","tags":["prep","cond"],"eq":["bw"],"req":[],"tier":1,"dose":"20m","cues":["Drive the knee up, land on the ball of the foot","Opposite arm drives with the knee","Stay light and bouncy"],"steps":["Start in a relaxed position with one leg slightly forward. This will be your starting position.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."],"muscles":["quadriceps","abductors","adductors","calves","glutes","hamstrings"],"img":["img/ex/skips-0.jpg","img/ex/skips-1.jpg"]},{"id":"butt-kicks","name":"Butt Kicks","tags":["prep","quads"],"eq":["bw"],"req":[],"tier":1,"dose":"20m","cues":["Heel to glute, quick contacts","Stay tall","Arms pump like running"],"steps":["Begin by standing on one leg, with the bent knee raised. This will be your start position.","Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.","Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.","Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill."],"muscles":["quadriceps","calves","hamstrings"],"img":["img/ex/butt-kicks-0.jpg","img/ex/butt-kicks-1.jpg"]},{"id":"carioca","name":"Carioca","tags":["prep","lateral","hips"],"eq":["bw"],"req":[],"tier":2,"dose":"15m/s","cues":["Move sideways crossing the trailing leg front then back","Let the hips rotate, shoulders stay square","Start slow, then speed up"],"steps":["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."],"muscles":["adductors","abdominals","abductors","calves","glutes","hamstrings","quadriceps"],"img":["img/ex/carioca-0.jpg","img/ex/carioca-1.jpg"]},{"id":"crossover-reverse-lunge","name":"Crossover Reverse Lunge","tags":["prep","mobility","glutes","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"5/s","cues":["Step back and across behind you, like a curtsy","Feel the stretch in the outside of the front hip","Push through the front heel to stand"],"steps":["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."],"muscles":["lower back","abdominals","abductors","glutes","hamstrings","quadriceps"],"img":["img/ex/crossover-reverse-lunge-0.jpg","img/ex/crossover-reverse-lunge-1.jpg"]},{"id":"scap-pull-up","name":"Scap Pull-Up","tags":["prep","prehab","vpull","shoulders"],"eq":["bar"],"req":[],"tier":1,"dose":"8","cues":["Dead hang, arms straight the whole time","Pull shoulders down away from the ears","Pause, then relax back to the hang"],"steps":["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."],"muscles":["traps","lats","middle back"],"img":["img/ex/scap-pull-up-0.jpg","img/ex/scap-pull-up-1.jpg"]},{"id":"segmental-bridge","name":"Segmental Bridge","tags":["prep","mobility","back","glutes"],"eq":["bw"],"req":[],"tier":1,"dose":"8","cues":["Tuck the pelvis, then peel the spine up one vertebra at a time","Lower the same way, top to bottom","Great low-back wake-up"],"steps":["Lie down with your feet on the floor, heels directly under your knees.","Lift only your tailbone to the ceiling to stretch your lower back. (Don't lift the entire spine yet.) Pull in your stomach.","To go into a bridge, lift the entire spine except the neck."],"muscles":["lower back"],"img":["img/ex/segmental-bridge-0.jpg","img/ex/segmental-bridge-1.jpg"]},{"id":"shoulder-pass-through","name":"Shoulder Pass-Through","tags":["prep","mobility","shoulders","chest"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Hold a band, towel or stick wide","Lift it over your head and behind, arms straight","Narrow the grip as it gets easy"],"steps":["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.","Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further."],"muscles":["shoulders","biceps","chest"],"img":["img/ex/shoulder-pass-through-0.jpg","img/ex/shoulder-pass-through-1.jpg"]},{"id":"spiderman-crawl","name":"Spiderman Crawl","tags":["prep","core","hips"],"eq":["bw"],"req":[],"tier":2,"dose":"6/s","cues":["Crawl forward bringing the knee to the elbow","Keep the hips low","Slow and controlled"],"steps":["Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.","Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.","Return this leg to the starting position and repeat on the opposite side."],"muscles":["abdominals","chest","shoulders","triceps"],"img":["img/ex/spiderman-crawl-0.jpg","img/ex/spiderman-crawl-1.jpg"]},{"id":"90-90-hip-switch","name":"90/90 Hip Switch","tags":["prep","mobility","hips","glutes"],"eq":["bw"],"req":[],"tier":1,"dose":"6/s","cues":["Sit with both knees bent to 90°, one in front, one to the side","Rotate both knees to the other side without using your hands if you can","Sit tall, lead with the knees"],"steps":["Sit on the floor. Place your front leg bent at 90° in front of you and your back leg bent at 90° out to the side.","Keep your chest tall and hands lightly behind you (or off the floor to progress).","Lift both knees and rotate them to the other side so the legs switch roles.","Pause in each position, leaning gently over the front shin."],"muscles":[],"img":[]},{"id":"thoracic-open-book","name":"Thoracic Open Book","tags":["prep","mobility","tspine","chest"],"eq":["bw"],"req":[],"tier":1,"dose":"6/s","cues":["Lie on your side, knees bent up to hip height","Open the top arm like a book, follow it with your eyes","Keep knees together and on the floor"],"steps":["Lie on your side with hips and knees bent to 90°, arms straight out in front, palms together.","Keeping your knees stacked, sweep the top arm up and over to the other side.","Let your upper back rotate and breathe out at the end range.","Return slowly and repeat, then switch sides."],"muscles":[],"img":[]},{"id":"deep-squat-hold","name":"Deep Squat Hold","tags":["prep","mobility","hips","ankles","groin"],"eq":["bw"],"req":[],"tier":1,"dose":"40s","cues":["Sit down into the deepest squat you can with heels down","Elbows push knees out, chest up","Hold something in front if needed"],"steps":["Stand with feet slightly wider than shoulders, toes turned out a little.","Sit all the way down into a deep squat, keeping heels on the floor.","Use your elbows to gently press the knees out and keep your chest up.","Shift side to side and breathe. Hold a door frame for support if needed."],"muscles":[],"img":[]},{"id":"broad-jump","name":"Broad Jump","tags":["power"],"eq":["bw"],"req":[],"tier":1,"dose":"4","cues":["Big arm swing, explode forward","Land soft and quiet in a half squat","Reset fully between reps"],"steps":["This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.","Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.","Attempt to land with your feet out in front you, reaching as far as possible with your legs.","Measure the distance from your landing point to the starting point and track results."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/broad-jump-0.jpg","img/ex/broad-jump-1.jpg"]},{"id":"jump-squat","name":"Jump Squat","tags":["power","squat"],"eq":["bw"],"req":[],"tier":1,"dose":"5","cues":["Quick dip to quarter squat, jump as high as you can","Land soft, knees tracking over toes","Quality over quantity"],"steps":["Cross your arms over your chest.","With your head up and your back straight, position your feet at shoulder width.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.","When you touch the floor again, immediately squat down and jump again.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/jump-squat-0.jpg","img/ex/jump-squat-1.jpg"]},{"id":"box-jump","name":"Box Jump","tags":["power"],"eq":["bw"],"req":["bench"],"tier":1,"dose":"4","cues":["Jump up, land in the same position you took off from","Step down — don't jump down","Pick a box you can land quietly on"],"steps":["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."],"muscles":["hamstrings","abductors","adductors","calves","glutes","quadriceps"],"img":["img/ex/box-jump-0.jpg","img/ex/box-jump-1.jpg"]},{"id":"lateral-bound","name":"Lateral Bound","tags":["power","lateral"],"eq":["bw"],"req":[],"tier":2,"dose":"4/s","cues":["Push off one leg sideways, stick the landing on the other","Hold the landing for 1 second","Knee stays over the foot"],"steps":["Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.","Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.","Immediately push off and extend, attempting to bound to the side as far as possible.","Upon landing, immediately push off in the opposite direction, returning to your original start position.","Continue back and forth for several repetitions."],"muscles":["adductors","abductors","calves","glutes","hamstrings","quadriceps"],"img":["img/ex/lateral-bound-0.jpg","img/ex/lateral-bound-1.jpg"]},{"id":"split-jump","name":"Split Jump","tags":["power","single"],"eq":["bw"],"req":[],"tier":2,"dose":"4/s","cues":["Start in a lunge, jump and switch legs in the air","Land softly in the opposite lunge","Stay tall through the torso"],"steps":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump, bring your feet together, and move them back to their initial positions as you land.","Absorb the impact by reverting back to the starting position."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/split-jump-0.jpg","img/ex/split-jump-1.jpg"]},{"id":"tuck-jump","name":"Tuck Jump","tags":["power"],"eq":["bw"],"req":[],"tier":2,"dose":"5","cues":["Jump and pull knees to chest","Land softly and rebound","Stop if landings get loud"],"steps":["Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.","Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."],"muscles":["hamstrings","abductors","adductors","calves","glutes","quadriceps"],"img":["img/ex/tuck-jump-0.jpg","img/ex/tuck-jump-1.jpg"]},{"id":"continuous-hops","name":"Continuous Hops","tags":["power"],"eq":["bw"],"req":[],"tier":2,"dose":"5","cues":["Two-footed hops forward, minimal ground contact","Stiff ankles, quick off the floor","Arms drive each hop"],"steps":["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles."],"muscles":["hamstrings","abductors","adductors","calves","glutes","hamstrings"],"img":["img/ex/continuous-hops-0.jpg","img/ex/continuous-hops-1.jpg"]},{"id":"single-leg-lateral-hop","name":"Single-Leg Lateral Hop","tags":["power","lateral","ankles"],"eq":["bw"],"req":[],"tier":2,"dose":"5/s","cues":["Hop side to side on one leg over a line","Stick each landing briefly at first","Great for ankle stability"],"steps":["Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.","To begin, execute a counterjump to hop sideways over the cone.","Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.","Continue hopping back and forth."],"muscles":["quadriceps","abductors","adductors","calves","hamstrings"],"img":["img/ex/single-leg-lateral-hop-0.jpg","img/ex/single-leg-lateral-hop-1.jpg"]},{"id":"plyo-push-up","name":"Plyo Push-Up","tags":["power","hpush"],"eq":["bw"],"req":[],"tier":3,"dose":"5","cues":["Explode up so the hands leave the floor","Land soft with bent elbows","Do from knees or an incline to start"],"steps":["Move into a prone position on the floor, supporting your weight on your hands and toes.","Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.","Descend by flexing at the elbow, lowering your chest towards the ground.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.","Return to the starting position and repeat the exercise.","For added difficulty, add claps into the movement while you are air borne."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/plyo-push-up-0.jpg","img/ex/plyo-push-up-1.jpg"]},{"id":"med-ball-slam","name":"Med Ball Slam","tags":["power","cond","core"],"eq":["mb"],"req":[],"tier":1,"dose":"6","cues":["Reach tall, then slam the ball with your whole body","Hinge at the hips as you slam","Catch on the bounce or pick up and repeat"],"steps":["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."],"muscles":["lats"],"img":["img/ex/med-ball-slam-0.jpg","img/ex/med-ball-slam-1.jpg"]},{"id":"med-ball-chest-pass","name":"Med Ball Chest Pass","tags":["power","hpush"],"eq":["mb"],"req":[],"tier":1,"dose":"6","cues":["Throw against a wall from the chest","Step into each throw","Max intent every rep"],"steps":["You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.","Begin facing your partner holding the medicine ball at your torso with both hands.","Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.","Your partner should catch the ball, and throw it back to you.","Receive the throw with both hands at chest height."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/med-ball-chest-pass-0.jpg","img/ex/med-ball-chest-pass-1.jpg"]},{"id":"rotational-scoop-toss","name":"Rotational Scoop Toss","tags":["power","core"],"eq":["mb"],"req":[],"tier":2,"dose":"5/s","cues":["Side-on to a wall, load the back hip","Rotate hard and release from the hip","Power comes from the legs, not the arms"],"steps":["Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.","Begin by thrusting the hips forward as you extend through the legs, jumping up.","As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you."],"muscles":["shoulders","abdominals","hamstrings","quadriceps"],"img":["img/ex/rotational-scoop-toss-0.jpg","img/ex/rotational-scoop-toss-1.jpg"]},{"id":"backward-med-ball-throw","name":"Backward Med Ball Throw","tags":["power","hinge"],"eq":["mb"],"req":[],"tier":2,"dose":"4","cues":["Hinge down with the ball between the knees","Explode up and throw it backwards overhead","Full hip extension"],"steps":["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."],"muscles":["shoulders"],"img":["img/ex/backward-med-ball-throw-0.jpg","img/ex/backward-med-ball-throw-1.jpg"]},{"id":"kettlebell-swing","name":"Kettlebell Swing","tags":["power","hinge","cond"],"eq":["kb"],"req":[],"tier":1,"dose":"12","cues":["Hike the bell back, hinge — don't squat","Snap the hips forward, bell floats to chest height","Plank at the top: glutes and abs tight","Two hands or one hand — same pattern"],"steps":[],"muscles":["hamstrings","calves","glutes","lower back","shoulders"],"img":["img/ex/kettlebell-swing-0.jpg","img/ex/kettlebell-swing-1.jpg"]},{"id":"kettlebell-clean","name":"Kettlebell Clean","tags":["power","hinge"],"eq":["kb"],"req":[],"tier":2,"dose":"5/s","cues":["Small hike, drive the hips","Keep the bell close, elbow tight to the ribs","Let the bell roll around the hand into the rack — no banging"],"steps":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times."],"muscles":["hamstrings","calves","glutes","lower back","shoulders","traps"],"img":["img/ex/kettlebell-clean-0.jpg","img/ex/kettlebell-clean-1.jpg"]},{"id":"kettlebell-snatch","name":"Kettlebell Snatch","tags":["power","cond","hinge","vpush"],"eq":["kb"],"req":[],"tier":3,"dose":"5/s","cues":["Hike, drive the hips, high pull","Punch through at the top so the bell doesn't flip onto the wrist","Master the swing and clean first"],"steps":["Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.","Look straight ahead and swing the kettlebell back between your legs.","Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead."],"muscles":["shoulders","calves","glutes","hamstrings","lower back","traps","triceps"],"img":["img/ex/kettlebell-snatch-0.jpg","img/ex/kettlebell-snatch-1.jpg"]},{"id":"kettlebell-push-press","name":"Kettlebell Push Press","tags":["power","vpush"],"eq":["kb"],"req":[],"tier":2,"dose":"5/s","cues":["Bell in the rack, short dip with the knees","Drive the legs and punch it overhead","Lower with control back to the rack"],"steps":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Lower the weight to perform the next repetition."],"muscles":["shoulders","calves","quadriceps","triceps"],"img":["img/ex/kettlebell-push-press-0.jpg","img/ex/kettlebell-push-press-1.jpg"]},{"id":"dumbbell-hang-clean","name":"Dumbbell Hang Clean","tags":["power","hinge"],"eq":["db"],"req":[],"tier":2,"dose":"5","cues":["Hinge with dumbbells at the knees","Jump-shrug and pull them up close","Catch on the shoulders in a quarter squat"],"steps":["Begin standing with a dumbbell in each hand with your feet shoulder width apart.","Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.","To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.","After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.","Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders."],"muscles":["hamstrings","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"img":["img/ex/dumbbell-hang-clean-0.jpg","img/ex/dumbbell-hang-clean-1.jpg"]},{"id":"dumbbell-swing","name":"Dumbbell Swing","tags":["power","hinge","cond"],"eq":["db"],"req":[],"tier":1,"dose":"12","cues":["Hold one dumbbell by the end","Hinge and hike back, then snap the hips","Arms are just ropes — hips do the work"],"steps":["Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.","Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."],"muscles":["hamstrings","glutes","quadriceps","shoulders"],"img":["img/ex/dumbbell-swing-0.jpg","img/ex/dumbbell-swing-1.jpg"]},{"id":"barbell-hang-clean","name":"Barbell Hang Clean","tags":["power","hinge"],"eq":["bb"],"req":[],"tier":3,"dose":"3","cues":["Bar at mid-thigh, hinge slightly","Jump and shrug, pull yourself under","Fast elbows into the front rack"],"steps":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"muscles":["quadriceps","calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"img":["img/ex/barbell-hang-clean-0.jpg","img/ex/barbell-hang-clean-1.jpg"]},{"id":"barbell-push-press","name":"Barbell Push Press","tags":["power","vpush"],"eq":["bb"],"req":[],"tier":2,"dose":"4","cues":["Bar in the front rack, short vertical dip","Drive with the legs and press to lockout","Head through at the top"],"steps":[],"muscles":["shoulders","quadriceps","triceps"],"img":["img/ex/barbell-push-press-0.jpg","img/ex/barbell-push-press-1.jpg"]},{"id":"star-jumps","name":"Star Jumps","tags":["cond","prep","power"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Jump out into a big X shape","Land softly with knees bent","Keep a steady rhythm"],"steps":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.","As you land, bring your limbs back in and absorb your impact through the legs."],"muscles":["quadriceps","calves","glutes","hamstrings","shoulders"],"img":["img/ex/star-jumps-0.jpg","img/ex/star-jumps-1.jpg"]},{"id":"bodyweight-squat","name":"Bodyweight Squat","tags":["squat","prep"],"eq":["bw"],"req":[],"tier":1,"dose":"12","cues":["Feet shoulder-width, sit between the hips","Chest up, knees track over toes","Go as deep as you control"],"steps":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"muscles":["quadriceps","glutes","hamstrings"],"img":["img/ex/bodyweight-squat-0.jpg","img/ex/bodyweight-squat-1.jpg"]},{"id":"goblet-squat","name":"Goblet Squat","tags":["squat"],"eq":["kb","db"],"req":[],"tier":1,"dose":"8","cues":["Bell at the chest, elbows down","Sit down between the knees, chest tall","Pause at the bottom for a better position"],"steps":["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings","shoulders"],"img":["img/ex/goblet-squat-0.jpg","img/ex/goblet-squat-1.jpg"]},{"id":"double-kettlebell-front-squat","name":"Double Kettlebell Front Squat","tags":["squat"],"eq":["kb"],"req":[],"tier":2,"dose":"6","cues":["Two bells in the rack, wrists straight","Brace hard, sit down tall","Drive up through the whole foot"],"steps":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.","Rise back up by driving through your heels and repeat."],"muscles":["quadriceps","calves","glutes"],"img":["img/ex/double-kettlebell-front-squat-0.jpg","img/ex/double-kettlebell-front-squat-1.jpg"]},{"id":"dumbbell-squat","name":"Dumbbell Squat","tags":["squat"],"eq":["db"],"req":[],"tier":1,"dose":"10","cues":["Dumbbells at your sides","Sit back and down, chest up","Full foot pressure"],"steps":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings","lower back"],"img":["img/ex/dumbbell-squat-0.jpg","img/ex/dumbbell-squat-1.jpg"]},{"id":"box-squat","name":"Box Squat","tags":["squat"],"eq":["bw","db","kb"],"req":["bench"],"tier":1,"dose":"10","cues":["Sit back to the box, touch lightly","Don't relax on the box","Stand up driving the knees out"],"steps":["Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings","lower back"],"img":["img/ex/box-squat-0.jpg","img/ex/box-squat-1.jpg"]},{"id":"back-squat","name":"Back Squat","tags":["squat"],"eq":["bb"],"req":[],"tier":2,"dose":"5","cues":["Bar on the upper back, brace before you descend","Knees out, sit down between the hips","Drive up keeping chest and hips rising together"],"steps":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings","lower back"],"img":["img/ex/back-squat-0.jpg","img/ex/back-squat-1.jpg"]},{"id":"front-squat","name":"Front Squat","tags":["squat"],"eq":["bb"],"req":[],"tier":3,"dose":"5","cues":["Elbows high, bar on the shoulders","Stay upright, sit straight down","Lead with the elbows on the way up"],"steps":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/front-squat-0.jpg","img/ex/front-squat-1.jpg"]},{"id":"kettlebell-thruster","name":"Kettlebell Thruster","tags":["squat","vpush","cond"],"eq":["kb","db"],"req":[],"tier":2,"dose":"8","cues":["Front squat into a press in one movement","Use the drive from the legs to press","Lower the bell back to the rack as you sit"],"steps":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.","Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.","At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.","As you begin the next repetition, return the weights to the shoulders."],"muscles":["shoulders","quadriceps","triceps"],"img":["img/ex/kettlebell-thruster-0.jpg","img/ex/kettlebell-thruster-1.jpg"]},{"id":"glute-bridge","name":"Glute Bridge","tags":["hinge","glutes","prep"],"eq":["bw"],"req":[],"tier":1,"dose":"12","cues":["Feet flat, heels close to glutes","Drive the hips up by squeezing glutes","Ribs down, don't arch the low back"],"steps":["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."],"muscles":["glutes","hamstrings"],"img":["img/ex/glute-bridge-0.jpg","img/ex/glute-bridge-1.jpg"]},{"id":"single-leg-glute-bridge","name":"Single-Leg Glute Bridge","tags":["hinge","glutes","single"],"eq":["bw"],"req":[],"tier":1,"dose":"10/s","cues":["One foot planted, other knee to chest","Push through the heel, hips level","Pause at the top"],"steps":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"muscles":["glutes","hamstrings"],"img":["img/ex/single-leg-glute-bridge-0.jpg","img/ex/single-leg-glute-bridge-1.jpg"]},{"id":"kettlebell-deadlift","name":"Kettlebell Deadlift","tags":["hinge"],"eq":["kb","db"],"req":[],"tier":1,"dose":"10","cues":["Bell between the feet, push hips back","Flat back, lats tight, grip and pull the slack out","Stand tall by driving the floor away"],"steps":["Stand with the kettlebell between your feet, feet hip-width apart.","Push your hips back and bend your knees slightly to grab the handle with both hands. Keep your back flat.","Pull your shoulders down and tighten your lats, then drive through your feet to stand tall.","Squeeze your glutes at the top, then hinge back down with control."],"muscles":[],"img":[]},{"id":"single-leg-rdl","name":"Single-Leg RDL","tags":["hinge","single","control"],"eq":["bw","kb","db"],"req":[],"tier":2,"dose":"8/s","cues":["Hips square, reach the free leg back long","Weight in the hand opposite the standing leg","Soft standing knee, flat back"],"steps":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"muscles":["hamstrings","glutes","lower back"],"img":["img/ex/single-leg-rdl-0.jpg","img/ex/single-leg-rdl-1.jpg"]},{"id":"dumbbell-romanian-deadlift","name":"Dumbbell Romanian Deadlift","tags":["hinge","hams"],"eq":["db","kb"],"req":[],"tier":1,"dose":"10","cues":["Soft knees, push the hips back","Weights slide down the thighs","Stop when the hamstrings are loaded, back stays flat"],"steps":["Grasp a couple of dumbbells holding them by your side at arm's length.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"muscles":["hamstrings","glutes","lower back"],"img":["img/ex/dumbbell-romanian-deadlift-0.jpg","img/ex/dumbbell-romanian-deadlift-1.jpg"]},{"id":"romanian-deadlift","name":"Romanian Deadlift","tags":["hinge","hams"],"eq":["bb"],"req":[],"tier":2,"dose":"8","cues":["Start standing, push hips back","Bar stays in contact with the legs","Feel the hamstrings, then drive hips forward"],"steps":["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."],"muscles":["hamstrings","calves","glutes","lower back"],"img":["img/ex/romanian-deadlift-0.jpg","img/ex/romanian-deadlift-1.jpg"]},{"id":"deadlift","name":"Deadlift","tags":["hinge"],"eq":["bb"],"req":[],"tier":2,"dose":"5","cues":["Bar over mid-foot, shins to bar","Chest up, pull the slack out, then push the floor away","Lock out with glutes, not by leaning back"],"steps":["Stand in front of a loaded barbell.","While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.","Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.","Perform the amount of repetitions prescribed in the program."],"muscles":["lower back","calves","forearms","glutes","hamstrings","lats","middle back","quadriceps","traps"],"img":["img/ex/deadlift-0.jpg","img/ex/deadlift-1.jpg"]},{"id":"trap-bar-deadlift","name":"Trap Bar Deadlift","tags":["hinge"],"eq":["bb"],"req":[],"tier":1,"dose":"5","cues":["Stand in the centre, grab the handles","Hips down, chest up, brace","Push the floor away"],"steps":["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.","Lower your hips, look forward with your head and keep your chest up.","Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.","At the completion of the movement, lower the weight back to the ground under control."],"muscles":["quadriceps","glutes","hamstrings"],"img":["img/ex/trap-bar-deadlift-0.jpg","img/ex/trap-bar-deadlift-1.jpg"]},{"id":"hip-thrust","name":"Hip Thrust","tags":["hinge","glutes"],"eq":["bb","db"],"req":["bench"],"tier":2,"dose":"10","cues":["Upper back on the bench, weight in the hip crease","Drive hips to full extension","Chin tucked, ribs down"],"steps":["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."],"muscles":["glutes","calves","hamstrings"],"img":["img/ex/hip-thrust-0.jpg","img/ex/hip-thrust-1.jpg"]},{"id":"band-good-morning","name":"Band Good Morning","tags":["hinge","hams"],"eq":["band"],"req":[],"tier":1,"dose":"12","cues":["Stand on the band, loop it behind the neck","Hinge back with a flat back","Snap the hips forward"],"steps":["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."],"muscles":["hamstrings","glutes","lower back"],"img":["img/ex/band-good-morning-0.jpg","img/ex/band-good-morning-1.jpg"]},{"id":"cable-pull-through","name":"Cable Pull-Through","tags":["hinge","glutes"],"eq":["cable","band"],"req":[],"tier":1,"dose":"12","cues":["Face away, rope between the legs","Hinge back, then drive the hips through","Squeeze glutes at the top"],"steps":["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."],"muscles":["glutes","hamstrings","lower back"],"img":["img/ex/cable-pull-through-0.jpg","img/ex/cable-pull-through-1.jpg"]},{"id":"nordic-curl","name":"Nordic Curl","tags":["hinge","hams"],"eq":["bw"],"req":[],"tier":3,"dose":"4","cues":["Anchor the heels, kneel tall","Lower forward as slowly as possible","Catch with your hands, push back up"],"steps":["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.","This will be your starting position. Lower yourself under control until your knees are almost completely straight.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."],"muscles":["hamstrings","calves","glutes","lower back"],"img":["img/ex/nordic-curl-0.jpg","img/ex/nordic-curl-1.jpg"]},{"id":"reverse-lunge","name":"Reverse Lunge","tags":["single","squat"],"eq":["bw","db","kb"],"req":[],"tier":1,"dose":"8/s","cues":["Step back, drop the back knee toward the floor","Most weight in the front heel","Torso tall, drive up through the front leg"],"steps":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.","Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.","Now repeat with the opposite leg."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/reverse-lunge-0.jpg","img/ex/reverse-lunge-1.jpg"]},{"id":"forward-lunge","name":"Forward Lunge","tags":["single","squat"],"eq":["bw","db","kb"],"req":[],"tier":1,"dose":"8/s","cues":["Step out long, both knees to 90°","Front knee tracks over the toes","Push back to the start"],"steps":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/forward-lunge-0.jpg","img/ex/forward-lunge-1.jpg"]},{"id":"split-squat","name":"Split Squat","tags":["single","squat"],"eq":["bw","db","kb"],"req":[],"tier":1,"dose":"8/s","cues":["Staggered stance, feet stay put","Straight down and up like an elevator","Back knee kisses the floor"],"steps":["Position yourself into a staggered stance with the rear foot elevated and front foot forward.","Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.","Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.","At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."],"muscles":["quadriceps","glutes","hamstrings"],"img":["img/ex/split-squat-0.jpg","img/ex/split-squat-1.jpg"]},{"id":"bulgarian-split-squat","name":"Bulgarian Split Squat","tags":["single","squat"],"eq":["bw","db","kb","bb"],"req":["bench"],"tier":2,"dose":"8/s","cues":["Rear foot up on a bench","Lean slightly forward for glutes, upright for quads","Front foot far enough out so the heel stays down"],"steps":["Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.","Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.","Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.","As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.","Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/bulgarian-split-squat-0.jpg","img/ex/bulgarian-split-squat-1.jpg"]},{"id":"step-up","name":"Step-Up","tags":["single","squat"],"eq":["bw","db","kb"],"req":["bench"],"tier":1,"dose":"8/s","cues":["Whole foot on the box","Drive through the top leg — don't push off the bottom one","Control the step down"],"steps":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/step-up-0.jpg","img/ex/step-up-1.jpg"]},{"id":"step-up-with-knee-drive","name":"Step-Up with Knee Drive","tags":["single","power"],"eq":["bw"],"req":["bench"],"tier":1,"dose":"8/s","cues":["Step up and drive the opposite knee high","Stand tall, balance for a beat","Athletic sprint posture"],"steps":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"muscles":["glutes","hamstrings","quadriceps"],"img":["img/ex/step-up-with-knee-drive-0.jpg","img/ex/step-up-with-knee-drive-1.jpg"]},{"id":"lunge-pass-through","name":"Lunge Pass-Through","tags":["single","core"],"eq":["kb"],"req":[],"tier":2,"dose":"6/s","cues":["Lunge and pass the bell under the front leg","Alternate legs each rep","Keep the torso upright"],"steps":["Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.","Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position.","Repeat the movement for the recommended amount of repetitions, alternating legs."],"muscles":["hamstrings","calves","glutes","quadriceps"],"img":["img/ex/lunge-pass-through-0.jpg","img/ex/lunge-pass-through-1.jpg"]},{"id":"single-leg-box-squat","name":"Single-Leg Box Squat","tags":["single","squat"],"eq":["bw"],"req":["bench"],"tier":2,"dose":"6/s","cues":["Stand on one leg in front of a box","Sit back to the box with control","Stand without rocking"],"steps":["Position a box in a rack. Secure a band or rope in place above the box.","Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance",". Continue stepping up and down on the same leg before switching to the opposite side."],"muscles":["quadriceps","glutes","hamstrings"],"img":["img/ex/single-leg-box-squat-0.jpg","img/ex/single-leg-box-squat-1.jpg"]},{"id":"pistol-squat","name":"Pistol Squat","tags":["single","squat","mobility"],"eq":["bw","kb"],"req":[],"tier":3,"dose":"4/s","cues":["One leg out in front, sit all the way down","Bell held out front as a counterweight","Use a box to limit depth while learning"],"steps":["Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.","Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.","Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.","Lower yourself again and repeat."],"muscles":["quadriceps","calves","glutes","hamstrings","shoulders"],"img":["img/ex/pistol-squat-0.jpg","img/ex/pistol-squat-1.jpg"]},{"id":"lateral-lunge","name":"Lateral Lunge","tags":["lateral","single","groin"],"eq":["bw","db","kb","bb"],"req":[],"tier":1,"dose":"6/s","cues":["Wide stance, sit into one hip","Other leg straight, both feet flat","Push back to the middle"],"steps":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.","Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.","Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.","After performing the recommended amount of reps, repeat the movement with the opposite leg."],"muscles":["quadriceps","calves","hamstrings","lower back"],"img":["img/ex/lateral-lunge-0.jpg","img/ex/lateral-lunge-1.jpg"]},{"id":"cossack-squat","name":"Cossack Squat","tags":["lateral","mobility","groin","hips","lmob"],"eq":["bw","kb","db"],"req":[],"tier":2,"dose":"5/s","cues":["Very wide stance, sit deep into one side","Straight leg toes point up","Hold a bell at the chest as a counterbalance"],"steps":["Take a very wide stance with toes slightly turned out.","Shift your weight to one side and sit down deep into that hip, keeping the heel down.","Let the straight leg rotate so the toes point up.","Keep your chest tall, then push back up through the middle to the other side."],"muscles":[],"img":[]},{"id":"banded-monster-walk","name":"Banded Monster Walk","tags":["lateral","glutes","prep","prehab"],"eq":["band"],"req":[],"tier":1,"dose":"10/s","cues":["Band around the knees or ankles","Half squat, step out wide and forward","Don't let the knees cave"],"steps":["Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.","To begin, take short steps forward alternating your left and right foot.","After several steps, do just the opposite and walk backward to where you started."],"muscles":["abductors"],"img":["img/ex/banded-monster-walk-0.jpg","img/ex/banded-monster-walk-1.jpg"]},{"id":"side-plank","name":"Side Plank","tags":["core","lateral"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Elbow under the shoulder, body in a straight line","Push the hip up to the ceiling","Bend the bottom knee to make it easier"],"steps":[],"muscles":["abdominals","shoulders"],"img":["img/ex/side-plank-0.jpg","img/ex/side-plank-1.jpg"]},{"id":"copenhagen-plank","name":"Copenhagen Plank","tags":["core","lateral","groin","control"],"eq":["bw"],"req":["bench"],"tier":2,"dose":"20s/s","cues":["Top leg on a bench, side plank","Lift the hips up — the inside of the top leg works","Use the knee on the bench to make it easier"],"steps":["Lie on your side next to a bench, with your top leg resting on it (knee for easier, ankle for harder).","Prop up on your elbow and lift your hips until your body is straight.","The bottom leg can hang or lift to the bench.","Hold, keeping your hips high and stacked."],"muscles":[],"img":[]},{"id":"push-up","name":"Push-Up","tags":["hpush"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Hands under shoulders, body in a straight line","Elbows at about 45°, chest to the floor","Squeeze glutes so the hips don't sag"],"steps":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/push-up-0.jpg","img/ex/push-up-1.jpg"]},{"id":"incline-push-up","name":"Incline Push-Up","tags":["hpush"],"eq":["bw"],"req":["bench"],"tier":1,"dose":"12","cues":["Hands on a bench or box","Full range, chest to the edge","Lower the incline as you get stronger"],"steps":["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.","Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.","Push body up until arms are extended. Repeat."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/incline-push-up-0.jpg","img/ex/incline-push-up-1.jpg"]},{"id":"feet-elevated-push-up","name":"Feet-Elevated Push-Up","tags":["hpush"],"eq":["bw"],"req":["bench"],"tier":2,"dose":"8","cues":["Feet on a bench","Keep the hips in line","Harder on the shoulders and upper chest"],"steps":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/feet-elevated-push-up-0.jpg","img/ex/feet-elevated-push-up-1.jpg"]},{"id":"push-up-to-side-plank","name":"Push-Up to Side Plank","tags":["hpush","core"],"eq":["bw"],"req":[],"tier":2,"dose":"5/s","cues":["Push-up, then rotate into a side plank","Stack the feet or stagger them","Back to the centre and switch sides"],"steps":["Get into pushup position on the toes with your hands just outside of shoulder width.","Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.","Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.","Lower the arm back to the floor for another pushup and then twist to the other side.","Repeat the series, alternating each side, for 10 or more reps."],"muscles":["chest","abdominals","shoulders","triceps"],"img":["img/ex/push-up-to-side-plank-0.jpg","img/ex/push-up-to-side-plank-1.jpg"]},{"id":"dumbbell-bench-press","name":"Dumbbell Bench Press","tags":["hpush"],"eq":["db"],"req":["bench"],"tier":1,"dose":"8","cues":["Shoulder blades pinched on the bench","Lower to the chest with elbows at 45°","Press up and slightly together"],"steps":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.","Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions of your training program."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/dumbbell-bench-press-0.jpg","img/ex/dumbbell-bench-press-1.jpg"]},{"id":"dumbbell-floor-press","name":"Dumbbell Floor Press","tags":["hpush"],"eq":["db"],"req":[],"tier":1,"dose":"10","cues":["Lie on the floor, knees bent","Lower until the upper arms touch the floor","Pause, then press"],"steps":["Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.","Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."],"muscles":["triceps","chest","shoulders"],"img":["img/ex/dumbbell-floor-press-0.jpg","img/ex/dumbbell-floor-press-1.jpg"]},{"id":"kettlebell-floor-press","name":"Kettlebell Floor Press","tags":["hpush","core"],"eq":["kb"],"req":[],"tier":1,"dose":"8/s","cues":["Bell on the back of the forearm","Lower until the elbow touches the floor","Don't let the body twist"],"steps":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."],"muscles":["chest","triceps"],"img":["img/ex/kettlebell-floor-press-0.jpg","img/ex/kettlebell-floor-press-1.jpg"]},{"id":"bench-press","name":"Bench Press","tags":["hpush"],"eq":["bb"],"req":["bench"],"tier":2,"dose":"6","cues":["Eyes under the bar, shoulder blades back and down","Touch the lower chest, elbows tucked","Drive the feet into the floor"],"steps":["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/bench-press-0.jpg","img/ex/bench-press-1.jpg"]},{"id":"kettlebell-overhead-press","name":"Kettlebell Overhead Press","tags":["vpush"],"eq":["kb"],"req":[],"tier":1,"dose":"6/s","cues":["Start in the rack, forearm vertical","Glutes tight, press straight up","Bicep finishes by the ear"],"steps":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .","Lower the pressed kettlebell to the starting position and immediately press with your other arm."],"muscles":["shoulders","triceps"],"img":["img/ex/kettlebell-overhead-press-0.jpg","img/ex/kettlebell-overhead-press-1.jpg"]},{"id":"single-arm-dumbbell-press","name":"Single-Arm Dumbbell Press","tags":["vpush","core"],"eq":["db"],"req":[],"tier":1,"dose":"8/s","cues":["Stand tall, brace against the lean","Press straight up","Slow lower"],"steps":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.","As you exhale, push the dumbbell up until your arm is fully extended.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch arms."],"muscles":["shoulders","triceps"],"img":["img/ex/single-arm-dumbbell-press-0.jpg","img/ex/single-arm-dumbbell-press-1.jpg"]},{"id":"dumbbell-overhead-press","name":"Dumbbell Overhead Press","tags":["vpush"],"eq":["db"],"req":[],"tier":1,"dose":"8","cues":["Dumbbells at the shoulders","Press up, don't arch the back","Lockout over the head"],"steps":["Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.","Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.","Pause, and slowly return the weight to the starting position."],"muscles":["shoulders","triceps"],"img":["img/ex/dumbbell-overhead-press-0.jpg","img/ex/dumbbell-overhead-press-1.jpg"]},{"id":"overhead-press","name":"Overhead Press","tags":["vpush"],"eq":["bb"],"req":[],"tier":2,"dose":"5","cues":["Bar on the front of the shoulders","Squeeze glutes, press straight up — move your head out of the way","Head through at the top"],"steps":["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.","Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"muscles":["shoulders","triceps"],"img":["img/ex/overhead-press-0.jpg","img/ex/overhead-press-1.jpg"]},{"id":"band-overhead-press","name":"Band Overhead Press","tags":["vpush"],"eq":["band"],"req":[],"tier":1,"dose":"12","cues":["Stand on the band, hands at the shoulders","Press overhead to lockout","Control the band back down"],"steps":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles and lift them so that the hands are at shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.","As you exhale, lift the handles up until your arms are fully extended overhead."],"muscles":["shoulders","triceps"],"img":["img/ex/band-overhead-press-0.jpg","img/ex/band-overhead-press-1.jpg"]},{"id":"handstand-push-up","name":"Handstand Push-Up","tags":["vpush"],"eq":["bw"],"req":[],"tier":3,"dose":"4","cues":["Kick up against a wall","Lower head to the floor with control","Use a pike push-up to build up to it"],"steps":["With your back to the wall bend at the waist and place both hands on the floor at shoulder width.","Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.","Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.","Push yourself back up slowly as you exhale until your elbows are nearly locked.","Repeat for the recommended amount of repetitions."],"muscles":["shoulders","triceps"],"img":["img/ex/handstand-push-up-0.jpg","img/ex/handstand-push-up-1.jpg"]},{"id":"kettlebell-windmill","name":"Kettlebell Windmill","tags":["core","mobility","vpush","shoulders","hams","lmob","control"],"eq":["kb"],"req":[],"tier":2,"dose":"5/s","cues":["Bell locked out overhead, eyes on it","Push the hip out and slide the other hand down the leg","Arm stays vertical the whole time"],"steps":["Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after reaching the ground and reverse the motion back to the starting position."],"muscles":["abdominals","glutes","hamstrings","shoulders","triceps"],"img":["img/ex/kettlebell-windmill-0.jpg","img/ex/kettlebell-windmill-1.jpg"]},{"id":"inverted-row","name":"Inverted Row","tags":["hpull"],"eq":["trx","bb","bar"],"req":[],"tier":1,"dose":"10","cues":["Body straight like a plank","Pull the chest to the hands","Feet further forward = harder"],"steps":["Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"muscles":["middle back","biceps","lats"],"img":["img/ex/inverted-row-0.jpg","img/ex/inverted-row-1.jpg"]},{"id":"single-arm-dumbbell-row","name":"Single-Arm Dumbbell Row","tags":["hpull"],"eq":["db"],"req":["bench"],"tier":1,"dose":"10/s","cues":["Hand and knee on the bench, flat back","Pull the elbow to the hip","Don't twist the torso"],"steps":["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions.","Switch sides and repeat again with the other arm."],"muscles":["middle back","biceps","lats","shoulders"],"img":["img/ex/single-arm-dumbbell-row-0.jpg","img/ex/single-arm-dumbbell-row-1.jpg"]},{"id":"kettlebell-row","name":"Kettlebell Row","tags":["hpull"],"eq":["kb"],"req":[],"tier":1,"dose":"10/s","cues":["Staggered stance, hinge forward","Row to the hip, elbow close","Pause and squeeze at the top"],"steps":["Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat."],"muscles":["middle back","biceps","lats"],"img":["img/ex/kettlebell-row-0.jpg","img/ex/kettlebell-row-1.jpg"]},{"id":"barbell-row","name":"Barbell Row","tags":["hpull"],"eq":["bb"],"req":[],"tier":2,"dose":"8","cues":["Hinge to about 45°, flat back","Pull the bar to the belly button","Control the lower"],"steps":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["middle back","biceps","lats","shoulders"],"img":["img/ex/barbell-row-0.jpg","img/ex/barbell-row-1.jpg"]},{"id":"seated-cable-row","name":"Seated Cable Row","tags":["hpull"],"eq":["cable"],"req":[],"tier":1,"dose":"10","cues":["Sit tall, slight lean","Pull to the stomach, shoulders down and back","Let the shoulder blades move forward on the return"],"steps":["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"muscles":["middle back","biceps","lats","shoulders"],"img":["img/ex/seated-cable-row-0.jpg","img/ex/seated-cable-row-1.jpg"]},{"id":"chest-supported-row","name":"Chest-Supported Row","tags":["hpull"],"eq":["db"],"req":["bench"],"tier":1,"dose":"10","cues":["Chest on an incline bench","Row both dumbbells to the hips","No momentum"],"steps":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"muscles":["middle back","biceps","forearms","lats","shoulders"],"img":["img/ex/chest-supported-row-0.jpg","img/ex/chest-supported-row-1.jpg"]},{"id":"renegade-row","name":"Renegade Row","tags":["hpull","core"],"eq":["kb","db"],"req":[],"tier":3,"dose":"6/s","cues":["Push-up position on the bells, wide feet","Row one side without twisting the hips","Push into the floor with the other hand"],"steps":["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."],"muscles":["middle back","abdominals","biceps","chest","lats","triceps"],"img":["img/ex/renegade-row-0.jpg","img/ex/renegade-row-1.jpg"]},{"id":"face-pull","name":"Face Pull","tags":["prehab","hpull","shoulders"],"eq":["cable","band"],"req":[],"tier":1,"dose":"15","cues":["Rope at face height","Pull to the eyes, hands finish beside the ears","Thumbs point back"],"steps":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."],"muscles":["shoulders","middle back"],"img":["img/ex/face-pull-0.jpg","img/ex/face-pull-1.jpg"]},{"id":"prone-y-t-w-raise","name":"Prone Y-T-W Raise","tags":["prehab","hpull","shoulders","back","prep"],"eq":["bw"],"req":[],"tier":1,"dose":"5","cues":["Lie face down, thumbs up","Lift arms into a Y, then T, then W — that's one rep","Squeeze the shoulder blades, keep the neck long"],"steps":["Lie face down with your forehead resting on a towel and arms overhead, thumbs pointing up.","Lift your arms into a Y shape by squeezing your shoulder blades. Pause, then lower.","Move your arms out to a T, lift and pause. Then bend the elbows into a W, pull them back and pause.","Y + T + W = one rep. Light and controlled."],"muscles":[],"img":[]},{"id":"band-external-rotation","name":"Band External Rotation","tags":["prehab","shoulders"],"eq":["band"],"req":[],"tier":1,"dose":"12/s","cues":["Elbow pinned to the side at 90°","Rotate the hand outward","Slow and controlled"],"steps":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"muscles":["shoulders"],"img":["img/ex/band-external-rotation-0.jpg","img/ex/band-external-rotation-1.jpg"]},{"id":"pull-up","name":"Pull-Up","tags":["vpull"],"eq":["bar"],"req":[],"tier":2,"dose":"5","cues":["Dead hang, shoulders engaged","Pull the chest to the bar","Full lower each rep"],"steps":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"muscles":["lats","biceps","middle back"],"img":["img/ex/pull-up-0.jpg","img/ex/pull-up-1.jpg"]},{"id":"chin-up","name":"Chin-Up","tags":["vpull"],"eq":["bar"],"req":[],"tier":2,"dose":"6","cues":["Palms facing you, shoulder-width","Chin over the bar","Slow 3-second lower"],"steps":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"muscles":["lats","biceps","forearms","middle back"],"img":["img/ex/chin-up-0.jpg","img/ex/chin-up-1.jpg"]},{"id":"band-assisted-pull-up","name":"Band-Assisted Pull-Up","tags":["vpull"],"eq":["bar"],"req":["band"],"tier":1,"dose":"6","cues":["Loop a band on the bar under the knee or foot","Same form as a full pull-up","Use a thinner band as you get stronger"],"steps":["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.","Pull the end of the band down, and place one bent knee into the loop, ensuring it won't slip out. Take a medium to wide grip on the bar. This will be your starting position.","Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.","After a brief pause, return to the starting position."],"muscles":["lats","abdominals","forearms","middle back"],"img":["img/ex/band-assisted-pull-up-0.jpg","img/ex/band-assisted-pull-up-1.jpg"]},{"id":"lat-pulldown","name":"Lat Pulldown","tags":["vpull"],"eq":["cable"],"req":[],"tier":1,"dose":"10","cues":["Slight lean back, chest up","Pull the bar to the upper chest","Elbows drive down to the ribs"],"steps":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"muscles":["lats","biceps","middle back","shoulders"],"img":["img/ex/lat-pulldown-0.jpg","img/ex/lat-pulldown-1.jpg"]},{"id":"dead-hang","name":"Dead Hang","tags":["vpull","mobility","stretch","shoulders","lats"],"eq":["bar"],"req":[],"tier":1,"dose":"30s","cues":["Hang with arms straight, relax the shoulders","Breathe and let the lats stretch","Builds grip and opens up the shoulders"],"steps":["Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides."],"muscles":["lats","biceps"],"img":["img/ex/dead-hang-0.jpg","img/ex/dead-hang-1.jpg"]},{"id":"plank","name":"Plank","tags":["core"],"eq":["bw"],"req":[],"tier":1,"dose":"30s","cues":["Elbows under the shoulders","Squeeze glutes, tuck the ribs","Straight line from head to heels"],"steps":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."],"muscles":["abdominals"],"img":["img/ex/plank-0.jpg","img/ex/plank-1.jpg"]},{"id":"dead-bug","name":"Dead Bug","tags":["core","prep"],"eq":["bw"],"req":[],"tier":1,"dose":"6/s","cues":["Lower back pressed into the floor","Extend opposite arm and leg slowly","Breathe out as you reach"],"steps":["Begin lying on your back with your hands extended above you toward the ceiling.","Bring your feet, knees, and hips up to 90 degrees.","Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.","Stay tight and return the working leg to the starting position.","Repeat on the opposite side, alternating until the set is complete."],"muscles":["abdominals"],"img":["img/ex/dead-bug-0.jpg","img/ex/dead-bug-1.jpg"]},{"id":"bird-dog","name":"Bird Dog","tags":["core","prep","back","control"],"eq":["bw"],"req":[],"tier":1,"dose":"6/s","cues":["On all fours, reach opposite arm and leg long","Hips stay level — imagine a glass of water on your back","Pause 2 seconds, then switch"],"steps":["Start on hands and knees, hands under shoulders and knees under hips.","Brace your core and slowly extend one arm forward and the opposite leg back.","Keep your hips and shoulders level and your back flat.","Pause, return to the start and switch sides."],"muscles":[],"img":[]},{"id":"hollow-hold","name":"Hollow Hold","tags":["core"],"eq":["bw"],"req":[],"tier":2,"dose":"20s","cues":["Low back glued to the floor","Arms and legs long, just off the floor","Bend the knees to make it easier"],"steps":["Lie on your back with your arms overhead.","Press your lower back into the floor and lift your shoulders, arms and legs slightly off the ground.","Keep everything long and tight like a banana shape.","Hold, breathing shallowly. Tuck the knees in if your back lifts."],"muscles":[],"img":[]},{"id":"pallof-press","name":"Pallof Press","tags":["core"],"eq":["cable","band"],"req":[],"tier":1,"dose":"10/s","cues":["Side-on to the anchor, hands at the chest","Press straight out and resist the rotation","Hold 2 seconds at full extension"],"steps":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."],"muscles":["abdominals","chest","shoulders","triceps"],"img":["img/ex/pallof-press-0.jpg","img/ex/pallof-press-1.jpg"]},{"id":"russian-twist","name":"Russian Twist","tags":["core"],"eq":["bw","mb","kb","db"],"req":[],"tier":1,"dose":"10/s","cues":["Sit tall, lean back slightly","Rotate from the ribs, not just the arms","Feet down to make it easier"],"steps":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.","Twist your torso to the right side until your arms are parallel with the floor while breathing out.","Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.","Repeat for the recommended amount of repetitions."],"muscles":["abdominals","lower back"],"img":["img/ex/russian-twist-0.jpg","img/ex/russian-twist-1.jpg"]},{"id":"mountain-climbers","name":"Mountain Climbers","tags":["core","cond"],"eq":["bw"],"req":[],"tier":1,"dose":"20/s","cues":["Plank position, drive the knees to the chest","Hips stay low","Quick but controlled"],"steps":["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."],"muscles":["quadriceps","chest","hamstrings","shoulders"],"img":["img/ex/mountain-climbers-0.jpg","img/ex/mountain-climbers-1.jpg"]},{"id":"hanging-leg-raise","name":"Hanging Leg Raise","tags":["core"],"eq":["bar"],"req":[],"tier":3,"dose":"8","cues":["Dead hang, no swinging","Lift the legs by curling the pelvis","Bent knees to make it easier"],"steps":["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.","Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.","Go back slowly to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"muscles":["abdominals"],"img":["img/ex/hanging-leg-raise-0.jpg","img/ex/hanging-leg-raise-1.jpg"]},{"id":"turkish-get-up","name":"Turkish Get-Up","tags":["core","mobility","shoulders","control"],"eq":["kb","db"],"req":[],"tier":2,"dose":"2/s","cues":["Eyes on the bell, arm locked the whole time","Roll to elbow → hand → bridge → sweep the leg → lunge → stand","Reverse every step on the way down","Start with a shoe on your fist"],"steps":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.","While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."],"muscles":["shoulders","abdominals","hamstrings","quadriceps","triceps"],"img":["img/ex/turkish-get-up-0.jpg","img/ex/turkish-get-up-1.jpg"]},{"id":"kettlebell-figure-8","name":"Kettlebell Figure-8","tags":["core"],"eq":["kb"],"req":[],"tier":2,"dose":"8/s","cues":["Half squat, pass the bell between the legs","Swap hands around each leg","Flat back, eyes forward"],"steps":["Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions."],"muscles":["abdominals","hamstrings","shoulders"],"img":["img/ex/kettlebell-figure-8-0.jpg","img/ex/kettlebell-figure-8-1.jpg"]},{"id":"superman","name":"Superman","tags":["core","back"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Lie face down, arms overhead","Lift arms, chest and legs together","Hold 2 seconds at the top"],"steps":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"muscles":["lower back","glutes","hamstrings"],"img":["img/ex/superman-0.jpg","img/ex/superman-1.jpg"]},{"id":"reverse-crunch","name":"Reverse Crunch","tags":["core"],"eq":["bw"],"req":[],"tier":1,"dose":"12","cues":["Lie down, knees up at 90°","Curl the hips off the floor toward the chest","Lower slowly"],"steps":["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.","Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.","While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"muscles":["abdominals"],"img":["img/ex/reverse-crunch-0.jpg","img/ex/reverse-crunch-1.jpg"]},{"id":"ab-rollout","name":"Ab Rollout","tags":["core"],"eq":["bb"],"req":[],"tier":2,"dose":"8","cues":["Kneel holding a bar or wheel","Roll out as far as you can without the back sagging","Pull back with the abs"],"steps":["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"muscles":["abdominals","lower back","shoulders"],"img":["img/ex/ab-rollout-0.jpg","img/ex/ab-rollout-1.jpg"]},{"id":"bear-crawl","name":"Bear Crawl","tags":["core","cond","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"20m","cues":["Hands and feet, knees hover an inch off the floor","Opposite hand and foot move together","Keep the back flat and hips low"],"steps":["Start on hands and knees, then lift your knees an inch off the floor.","Crawl forward moving the opposite hand and foot together.","Keep your back flat and hips level — don't let them pike up.","Crawl forward, backward or sideways."],"muscles":[],"img":[]},{"id":"farmers-carry","name":"Farmer's Carry","tags":["carry","core"],"eq":["kb","db","bb"],"req":[],"tier":1,"dose":"30m","cues":["Heavy weight in each hand","Stand tall, shoulders down","Short quick steps"],"steps":["There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren't available. Begin by standing between the implements.","After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.","Walk taking short, quick steps, and don't forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible."],"muscles":["forearms","abdominals","glutes","hamstrings","lower back","quadriceps","traps"],"img":["img/ex/farmers-carry-0.jpg","img/ex/farmers-carry-1.jpg"]},{"id":"suitcase-carry","name":"Suitcase Carry","tags":["carry","core","control"],"eq":["kb","db"],"req":[],"tier":1,"dose":"20m/s","cues":["Weight in one hand only","Don't lean — stay perfectly tall","Brace the opposite side"],"steps":["Pick up one heavy kettlebell or dumbbell in one hand.","Stand tall with your shoulders level — resist leaning toward the weight.","Walk with short, controlled steps.","Switch hands and repeat."],"muscles":[],"img":[]},{"id":"burpee","name":"Burpee","tags":["cond"],"eq":["bw"],"req":[],"tier":1,"dose":"8","cues":["Squat, kick back to a plank, chest to the floor","Jump the feet in and jump up","Step back and step in instead of jumping to scale"],"steps":["Squat down and put your hands on the floor.","Jump or step your feet back into a plank and lower your chest to the floor.","Push up and jump or step your feet back under you.","Stand and jump, clapping overhead."],"muscles":[],"img":[]},{"id":"jump-rope","name":"Jump Rope","tags":["cond","prep","calves"],"eq":["bw"],"req":[],"tier":1,"dose":"60s","cues":["Small hops off the balls of the feet","Wrists turn the rope, elbows close","No rope? Shadow jump"],"steps":["Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.","Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running."],"muscles":["quadriceps","calves","hamstrings"],"img":["img/ex/jump-rope-0.jpg","img/ex/jump-rope-1.jpg"]},{"id":"kettlebell-sumo-high-pull","name":"Kettlebell Sumo High Pull","tags":["cond","power"],"eq":["kb"],"req":[],"tier":2,"dose":"10","cues":["Wide stance, bell between the feet","Drive the hips and pull the bell to the chin","Elbows high"],"steps":["Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.","Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position."],"muscles":["traps","adductors","glutes","hamstrings","quadriceps","shoulders"],"img":["img/ex/kettlebell-sumo-high-pull-0.jpg","img/ex/kettlebell-sumo-high-pull-1.jpg"]},{"id":"sprints","name":"Sprints","tags":["cond","power"],"eq":["bw"],"req":[],"tier":2,"dose":"40m","cues":["Build up — start at 70% the first few","Drive the arms, tall posture","Walk back to recover"],"steps":["Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.","Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3","Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.","Continue alternating between legs until the set is complete."],"muscles":["abdominals"],"img":["img/ex/sprints-0.jpg","img/ex/sprints-1.jpg"]},{"id":"row-bike-intervals","name":"Row / Bike Intervals","tags":["cond"],"eq":["cardio"],"req":[],"tier":1,"dose":"60s","cues":["Rower or bike","Hard but sustainable for the work interval","Easy pace to recover"],"steps":["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."],"muscles":["quadriceps","biceps","calves","glutes","hamstrings","lower back","middle back"],"img":["img/ex/row-bike-intervals-0.jpg","img/ex/row-bike-intervals-1.jpg"]},{"id":"kneeling-hip-flexor-stretch","name":"Kneeling Hip Flexor Stretch","tags":["stretch","hips","quads"],"eq":["bw"],"req":[],"tier":1,"dose":"40s/s","cues":["Half-kneeling, tuck the pelvis under","Squeeze the back glute and shift forward slightly","Reach the arm up for more stretch"],"steps":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"muscles":["quadriceps","quadriceps"],"img":["img/ex/kneeling-hip-flexor-stretch-0.jpg","img/ex/kneeling-hip-flexor-stretch-1.jpg"]},{"id":"couch-stretch","name":"Couch Stretch","tags":["stretch","hips","quads"],"eq":["bw"],"req":[],"tier":2,"dose":"45s/s","cues":["Back knee in the corner of a wall or couch, shin up the wall","Front foot forward, squeeze the back glute","Sit tall slowly"],"steps":["Lie face down on the floor, with a rope, belt, or band looped around one foot.","Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg."],"muscles":["quadriceps"],"img":["img/ex/couch-stretch-0.jpg","img/ex/couch-stretch-1.jpg"]},{"id":"pigeon-stretch","name":"Pigeon Stretch","tags":["stretch","hips","glutes"],"eq":["bw"],"req":[],"tier":1,"dose":"45s/s","cues":["Front shin across the body, back leg long","Hips square to the floor","Fold forward over the front leg to deepen"],"steps":["From all fours, bring one knee forward behind the same-side wrist with the shin angled across your body.","Slide the other leg straight back and settle the hips toward the floor.","Stay upright or fold forward over the front leg.","Breathe and relax into it. Put a cushion under the hip if it doesn't reach the floor."],"muscles":[],"img":[]},{"id":"figure-4-stretch","name":"Figure-4 Stretch","tags":["stretch","glutes","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"40s/s","cues":["Lie on your back, ankle on the opposite knee","Pull the bottom thigh toward you","Keep the top foot flexed"],"steps":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."],"muscles":["glutes"],"img":["img/ex/figure-4-stretch-0.jpg","img/ex/figure-4-stretch-1.jpg"]},{"id":"knee-across-the-body","name":"Knee Across the Body","tags":["stretch","glutes","back"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Lie down, pull one knee across the body","Keep both shoulders down","Look the other way"],"steps":["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn't need to touch the floor if you're tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."],"muscles":["glutes","abductors","lower back"],"img":["img/ex/knee-across-the-body-0.jpg","img/ex/knee-across-the-body-1.jpg"]},{"id":"90-90-hamstring-stretch","name":"90/90 Hamstring Stretch","tags":["stretch","hams"],"eq":["bw"],"req":[],"tier":1,"dose":"40s/s","cues":["Lie on your back, hold behind the thigh at 90°","Straighten the knee until you feel the stretch","Flex the foot"],"steps":["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."],"muscles":["hamstrings","calves"],"img":["img/ex/90-90-hamstring-stretch-0.jpg","img/ex/90-90-hamstring-stretch-1.jpg"]},{"id":"seated-hamstring-stretch","name":"Seated Hamstring Stretch","tags":["stretch","hams","back"],"eq":["bw"],"req":[],"tier":1,"dose":"40s/s","cues":["One leg out, the other foot to the inner thigh","Hinge from the hips toward the toes","Long spine, don't round hard"],"steps":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."],"muscles":["hamstrings","calves"],"img":["img/ex/seated-hamstring-stretch-0.jpg","img/ex/seated-hamstring-stretch-1.jpg"]},{"id":"standing-hamstring-and-calf-stretch","name":"Standing Hamstring & Calf Stretch","tags":["stretch","hams","calves"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Heel forward, toes up","Hinge forward with a flat back","Pull the toes back for more calf"],"steps":["Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."],"muscles":["hamstrings"],"img":["img/ex/standing-hamstring-and-calf-stretch-0.jpg","img/ex/standing-hamstring-and-calf-stretch-1.jpg"]},{"id":"straddle-stretch","name":"Straddle Stretch","tags":["stretch","groin","hams"],"eq":["bw"],"req":[],"tier":1,"dose":"45s","cues":["Legs wide, toes up","Walk the hands forward from the hips","Back stays long"],"steps":["Begin in a seated, upright position. Start by extending your legs in front of you in a V.","With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds."],"muscles":["hamstrings","adductors","calves"],"img":["img/ex/straddle-stretch-0.jpg","img/ex/straddle-stretch-1.jpg"]},{"id":"butterfly-stretch","name":"Butterfly Stretch","tags":["stretch","groin","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"40s","cues":["Soles of the feet together","Let the knees fall open","Hinge forward gently"],"steps":["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."],"muscles":["adductors","hamstrings"],"img":["img/ex/butterfly-stretch-0.jpg","img/ex/butterfly-stretch-1.jpg"]},{"id":"wall-calf-stretch","name":"Wall Calf Stretch","tags":["stretch","calves","ankles"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Hands on the wall, back leg straight, heel down","Lean into the wall","Bend the back knee to target the soleus"],"steps":["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."],"muscles":["calves"],"img":["img/ex/wall-calf-stretch-0.jpg","img/ex/wall-calf-stretch-1.jpg"]},{"id":"soleus-stretch","name":"Soleus Stretch","tags":["stretch","calves","ankles"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Staggered stance, both knees bent","Sink down keeping the back heel on the floor","Feel it low in the calf"],"steps":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"muscles":["calves"],"img":["img/ex/soleus-stretch-0.jpg","img/ex/soleus-stretch-1.jpg"]},{"id":"side-lying-quad-stretch","name":"Side-Lying Quad Stretch","tags":["stretch","quads","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Lie on your side, grab the top ankle","Pull the heel toward the glute","Push the hip forward"],"steps":["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."],"muscles":["quadriceps"],"img":["img/ex/side-lying-quad-stretch-0.jpg","img/ex/side-lying-quad-stretch-1.jpg"]},{"id":"childs-pose","name":"Child's Pose","tags":["stretch","back","lats"],"eq":["bw"],"req":[],"tier":1,"dose":"45s","cues":["Knees wide, sit back on the heels","Reach the arms long","Breathe into the back of the ribs"],"steps":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"muscles":["lower back","glutes","middle back"],"img":["img/ex/childs-pose-0.jpg","img/ex/childs-pose-1.jpg"]},{"id":"wall-lat-stretch","name":"Wall Lat Stretch","tags":["stretch","lats","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Hand on the wall, step back and hinge","Push the hips away","Feel it along the side of the back"],"steps":["From a standing position, place a bent arm against a wall or doorway.","Slowly lean toward your arm until you feel a stretch in your lats."],"muscles":["lats"],"img":["img/ex/wall-lat-stretch-0.jpg","img/ex/wall-lat-stretch-1.jpg"]},{"id":"doorway-chest-stretch","name":"Doorway Chest Stretch","tags":["stretch","chest","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Forearm on a door frame, elbow at shoulder height","Step through gently","Don't let the shoulder roll forward"],"steps":["Start off by standing with your legs together, holding a bodybar or a broomstick.","Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.","Carefully lift the pole up and behind your head."],"muscles":["chest","shoulders"],"img":["img/ex/doorway-chest-stretch-0.jpg","img/ex/doorway-chest-stretch-1.jpg"]},{"id":"cross-body-shoulder-stretch","name":"Cross-Body Shoulder Stretch","tags":["stretch","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Pull the arm across the chest","Keep the shoulder down","Breathe and relax"],"steps":["Reach your left arm across your body and hold it straight."],"muscles":["shoulders"],"img":["img/ex/cross-body-shoulder-stretch-0.jpg","img/ex/cross-body-shoulder-stretch-1.jpg"]},{"id":"overhead-triceps-stretch","name":"Overhead Triceps Stretch","tags":["stretch","shoulders","lats"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Reach the hand down the back","Gently press the elbow back","Stay tall"],"steps":["Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."],"muscles":["triceps","lats"],"img":["img/ex/overhead-triceps-stretch-0.jpg","img/ex/overhead-triceps-stretch-1.jpg"]},{"id":"seated-spinal-twist","name":"Seated Spinal Twist","tags":["stretch","back","tspine","glutes"],"eq":["bw"],"req":[],"tier":1,"dose":"30s/s","cues":["Sit tall, cross one leg over","Twist toward the bent knee","Lengthen up, then rotate"],"steps":["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."],"muscles":["middle back","lats","lower back","neck","traps"],"img":["img/ex/seated-spinal-twist-0.jpg","img/ex/seated-spinal-twist-1.jpg"]},{"id":"upper-back-stretch","name":"Upper Back Stretch","tags":["stretch","back","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"30s","cues":["Clasp the hands in front","Round the upper back and push the hands away","Tuck the chin"],"steps":["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."],"muscles":["middle back","middle back"],"img":["img/ex/upper-back-stretch-0.jpg","img/ex/upper-back-stretch-1.jpg"]},{"id":"standing-side-bend","name":"Standing Side Bend","tags":["stretch","lats","back"],"eq":["bw"],"req":[],"tier":1,"dose":"20s/s","cues":["Reach one arm overhead and lean away","Hips stay centred","Long through the side of the body"],"steps":["Take a slightly wider than hip distance stance with your knees slightly bent.","Place your right hand on your right hip to support the spine.","Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.","Keep your weight evenly distributed between both legs (don't lean into your left hip). Switch sides."],"muscles":["abdominals"],"img":["img/ex/standing-side-bend-0.jpg","img/ex/standing-side-bend-1.jpg"]},{"id":"knees-to-chest","name":"Knees to Chest","tags":["stretch","back","glutes"],"eq":["bw"],"req":[],"tier":1,"dose":"30s","cues":["Lie on your back, hug both knees in","Rock gently side to side","Relax the low back"],"steps":["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles."],"muscles":["lower back","glutes"],"img":["img/ex/knees-to-chest-0.jpg","img/ex/knees-to-chest-1.jpg"]},{"id":"wrist-and-forearm-stretch","name":"Wrist & Forearm Stretch","tags":["stretch","wrists"],"eq":["bw"],"req":[],"tier":1,"dose":"30s","cues":["Kneel, palms down, fingers pointing to the knees","Gently lean back","Ease off if it pinches"],"steps":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."],"muscles":["forearms"],"img":["img/ex/wrist-and-forearm-stretch-0.jpg","img/ex/wrist-and-forearm-stretch-1.jpg"]},{"id":"overhead-reach","name":"Overhead Reach","tags":["stretch","shoulders","lats"],"eq":["bw"],"req":[],"tier":1,"dose":"20s","cues":["Clasp the hands, reach up tall","Ribs down","Breathe"],"steps":["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."],"muscles":["shoulders","chest","lats"],"img":["img/ex/overhead-reach-0.jpg","img/ex/overhead-reach-1.jpg"]},{"id":"foam-roll-quads","name":"Foam Roll — Quads","tags":["smr","quads"],"eq":["roller"],"req":[],"tier":1,"dose":"45s/s","cues":["Face down on the roller","Roll from hip to above the knee","Pause on tight spots"],"steps":["Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides."],"muscles":["quadriceps"],"img":["img/ex/foam-roll-quads-0.jpg","img/ex/foam-roll-quads-1.jpg"]},{"id":"foam-roll-hamstrings","name":"Foam Roll — Hamstrings","tags":["smr","hams"],"eq":["roller"],"req":[],"tier":1,"dose":"45s/s","cues":["Sit on the roller, hands behind","Cross one leg over for more pressure","Slow passes"],"steps":["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"muscles":["hamstrings"],"img":["img/ex/foam-roll-hamstrings-0.jpg","img/ex/foam-roll-hamstrings-1.jpg"]},{"id":"foam-roll-calves","name":"Foam Roll — Calves","tags":["smr","calves"],"eq":["roller"],"req":[],"tier":1,"dose":"45s/s","cues":["Roller under the calf","Turn the foot in and out","Stack the legs for more pressure"],"steps":["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"muscles":["calves"],"img":["img/ex/foam-roll-calves-0.jpg","img/ex/foam-roll-calves-1.jpg"]},{"id":"foam-roll-upper-back","name":"Foam Roll — Upper Back","tags":["smr","back","tspine"],"eq":["roller"],"req":[],"tier":1,"dose":"45s","cues":["Roller under the shoulder blades, hands across the chest","Lift the hips and roll slowly","Avoid the lower back"],"steps":["Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.","Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds."],"muscles":["middle back","traps"],"img":["img/ex/foam-roll-upper-back-0.jpg","img/ex/foam-roll-upper-back-1.jpg"]},{"id":"foam-roll-lats","name":"Foam Roll — Lats","tags":["smr","lats"],"eq":["roller"],"req":[],"tier":1,"dose":"40s/s","cues":["Lie on your side, roller under the armpit","Arm reaching overhead","Roll down the side of the back"],"steps":["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides."],"muscles":["lats"],"img":["img/ex/foam-roll-lats-0.jpg","img/ex/foam-roll-lats-1.jpg"]},{"id":"foam-roll-outer-thigh","name":"Foam Roll — Outer Thigh","tags":["smr","quads","hips"],"eq":["roller"],"req":[],"tier":1,"dose":"40s/s","cues":["Lie on your side on the roller","Top foot in front for support","Go slow — it's sensitive"],"steps":["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg."],"muscles":["abductors"],"img":["img/ex/foam-roll-outer-thigh-0.jpg","img/ex/foam-roll-outer-thigh-1.jpg"]},{"id":"foam-roll-glutes","name":"Foam Roll — Glutes","tags":["smr","glutes","hips"],"eq":["roller"],"req":[],"tier":1,"dose":"40s/s","cues":["Sit on the roller, ankle over the opposite knee","Lean into the crossed side","Small slow rolls"],"steps":["Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides."],"muscles":["glutes"],"img":["img/ex/foam-roll-glutes-0.jpg","img/ex/foam-roll-glutes-1.jpg"]},{"id":"foam-roll-adductors","name":"Foam Roll — Adductors","tags":["smr","groin"],"eq":["roller"],"req":[],"tier":1,"dose":"40s/s","cues":["Face down, one leg out to the side on the roller","Roll the inside of the thigh","Slow passes"],"steps":["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."],"muscles":["adductors"],"img":["img/ex/foam-roll-adductors-0.jpg","img/ex/foam-roll-adductors-1.jpg"]},{"id":"hip-cars","name":"Hip CARs","tags":["prep","mobility","cars","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"3/s","cues":["Hold a wall, brace everything except the moving hip","Knee up, out, rotate back and down — biggest circle you own","Slow: 10+ seconds per circle, both directions"],"steps":[],"muscles":[],"img":[]},{"id":"shoulder-cars","name":"Shoulder CARs","tags":["prep","mobility","cars","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"3/s","cues":["Make a tight fist, squeeze glutes and abs","Draw the biggest slow circle you can with a straight arm","Ribs stay down — only the shoulder moves"],"steps":[],"muscles":[],"img":[]},{"id":"quadruped-scapular-cars","name":"Quadruped Scapular CARs","tags":["prep","mobility","cars","shoulders","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"5","cues":["On all fours, elbows locked","Slowly circle the shoulder blades: forward, up, back, down","Both directions — chest moves, arms don't bend"],"steps":[],"muscles":[],"img":[]},{"id":"thread-the-needle","name":"Thread the Needle","tags":["prep","mobility","tspine","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"6/s","cues":["On all fours, reach one arm under the opposite armpit","Let the shoulder and ear sink to the floor","Then open the arm to the ceiling, eyes follow the hand"],"steps":[],"muscles":[],"img":[]},{"id":"knee-to-wall-ankle-rocks","name":"Knee-to-Wall Ankle Rocks","tags":["prep","mobility","ankles","calves"],"eq":["bw"],"req":[],"tier":1,"dose":"10/s","cues":["Half-kneel facing a wall, front foot a hand away","Drive the knee over the toes to touch the wall","Heel stays glued down — move the foot back as it frees up"],"steps":[],"muscles":[],"img":[]},{"id":"adductor-rock-back","name":"Adductor Rock-Back","tags":["prep","mobility","groin","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"8/s","cues":["On all fours, one leg straight out to the side","Sit the hips back towards the heel, flat back","Feel the stretch along the inner thigh, then return"],"steps":[],"muscles":[],"img":[]},{"id":"wall-slides","name":"Wall Slides","tags":["prep","mobility","prehab","shoulders","tspine"],"eq":["bw"],"req":[],"tier":1,"dose":"10","cues":["Back, head and arms against the wall in a goalpost","Slide the arms up without the low back arching","Pull the elbows down into the ribs to return"],"steps":[],"muscles":[],"img":[]},{"id":"shinbox-get-up","name":"Shinbox Get-Up","tags":["mobility","control","hips","glutes"],"eq":["bw"],"req":[],"tier":2,"dose":"4/s","cues":["Sit in a 90/90 position","Drive the front shin into the floor and rise to tall kneeling","Lower with control, switch sides — hands off the floor if you can"],"steps":[],"muscles":[],"img":[]},{"id":"jefferson-curl","name":"Jefferson Curl","tags":["mobility","lmob","hams","back"],"eq":["bw","kb","db"],"req":[],"tier":2,"dose":"6","cues":["Stand on a box or floor, light weight or none","Chin to chest, roll down one vertebra at a time","Roll back up slowly — very light, very slow"],"steps":[],"muscles":[],"img":[]},{"id":"goblet-prying-squat","name":"Goblet Prying Squat","tags":["lmob","mobility","squat","hips","groin","ankles"],"eq":["kb","db"],"req":[],"tier":1,"dose":"5","cues":["Hold the bell at the chest, sink into a deep squat","Hold ~5s at the bottom, elbows gently pry the knees open","Shift weight side to side across the ankles, then stand"],"steps":[],"muscles":[],"img":[]},{"id":"half-kneeling-kb-windmill","name":"Half-Kneeling KB Windmill","tags":["lmob","control","core","shoulders","hams"],"eq":["kb"],"req":[],"tier":2,"dose":"5/s","cues":["Half-kneel, bell locked out overhead on the front-leg side","Eyes on the bell, hinge the hips diagonally back","Free hand to the mat, then return tall — arm stays vertical"],"steps":[],"muscles":[],"img":[]},{"id":"kettlebell-arm-bar","name":"Kettlebell Arm Bar","tags":["lmob","control","shoulders","tspine"],"eq":["kb"],"req":[],"tier":2,"dose":"3/s","cues":["Lie down, press the bell up, cross the opposite leg over","Roll to your side then towards your belly, arm vertical","Hold 2–3 breaths, shoulder packed, then roll back"],"steps":[],"muscles":[],"img":[]},{"id":"kb-pullover-dead-bug","name":"KB Pullover Dead Bug","tags":["core","control"],"eq":["kb","db"],"req":[],"tier":1,"dose":"4/s","cues":["On your back, knees at 90°, bell over the chest","Lower the bell behind the head as one heel reaches to the floor","Low back stays pressed flat — slow and controlled"],"steps":[],"muscles":[],"img":[]},{"id":"single-leg-rdl-airplane","name":"Single-Leg RDL Airplane","tags":["control","single","hinge","hips","glutes"],"eq":["bw"],"req":[],"tier":2,"dose":"5/s","cues":["Balance on one leg, hinge to a horizontal T","Rotate the pelvis open to the side wall, then closed to the floor","Stand tall and squeeze the glute — use a wall for support at first"],"steps":[],"muscles":[],"img":[]},{"id":"bottoms-up-kb-press","name":"Bottoms-Up KB Press","tags":["vpush","control","prehab","shoulders"],"eq":["kb"],"req":[],"tier":2,"dose":"5/s","cues":["Hold the bell upside down, squeeze the handle hard","Press slowly overhead keeping it balanced","Lighter than you think — it's a stability drill"],"steps":[],"muscles":[],"img":[]},{"id":"half-get-up","name":"Half Get-Up","tags":["core","control","shoulders"],"eq":["kb","db","bw"],"req":[],"tier":1,"dose":"3/s","cues":["Turkish get-up to the tall-sit position only","Elbow, then hand, eyes on the bell","Reverse slowly — learn this before the full get-up"],"steps":[],"muscles":[],"img":[]},{"id":"front-rack-walk","name":"Front Rack Walk","tags":["carry","core","control"],"eq":["kb","db"],"req":[],"tier":1,"dose":"20m/s","cues":["Bell in the rack, tucked against the collarbone","Walk slow, heel to toe, ribs down","Don't lean away from the bell"],"steps":[],"muscles":[],"img":[]},{"id":"overhead-carry","name":"Overhead Carry","tags":["carry","core","control","shoulders"],"eq":["kb","db"],"req":[],"tier":2,"dose":"20m/s","cues":["Lock the bell out overhead, bicep by the ear","Walk tall and slow, ribs stacked over hips","Stop if the elbow starts to bend"],"steps":[],"muscles":[],"img":[]},{"id":"slow-high-knee-march","name":"Slow High-Knee March","tags":["control","core","hips","prep"],"eq":["bw","kb"],"req":[],"tier":1,"dose":"6/s","cues":["March in place, knee to hip height","Pause 2 seconds at the top on one leg","Stand tall — add a bell in the rack or overhead to progress"],"steps":[],"muscles":[],"img":[]},{"id":"single-leg-balance-reach","name":"Single-Leg Balance Reach","tags":["control","single","ankles","prep"],"eq":["bw"],"req":[],"tier":1,"dose":"5/s","cues":["Balance on one leg, slight knee bend","Reach the other foot forward, side and back like a clock","Foot stays rooted, hips level"],"steps":[],"muscles":[],"img":[]},{"id":"kettlebell-clean-and-press","name":"Kettlebell Clean & Press","tags":["vpush","power","hinge","cond"],"eq":["kb"],"req":[],"tier":2,"dose":"5/s","cues":["Clean the bell to the rack","Brace and press overhead, lock out","Lower to the rack, then back between the legs"],"steps":[],"muscles":[],"img":[]},{"id":"a-skip","name":"A-Skip","tags":["prep","power"],"eq":["bw"],"req":[],"tier":1,"dose":"20m","cues":["Skip with an exaggerated knee drive","Strike the ground under your hips","Opposite arm drives — stay tall"],"steps":[],"muscles":[],"img":[]},{"id":"pogo-hops","name":"Pogo Hops","tags":["power","prep","calves","ankles"],"eq":["bw"],"req":[],"tier":1,"dose":"20","cues":["Small, fast bounces off the balls of the feet","Knees nearly straight — the ankles do the work","Spend as little time on the ground as possible"],"steps":[],"muscles":[],"img":[]},{"id":"hurdle-hops","name":"Hurdle Hops","tags":["power"],"eq":["bw"],"req":[],"tier":2,"dose":"5","cues":["Jump over a low cone or line, feet together","Land softly and rebound straight away","Arms drive the jump"],"steps":["Set up a row of cones or other small barriers, placing them a few feet apart.","Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.","Continue until you have jumped over all of the cones."],"muscles":["quadriceps","abductors","adductors","calves","glutes","hamstrings"],"img":["img/ex/hurdle-hops-0.jpg","img/ex/hurdle-hops-1.jpg"]},{"id":"diagonal-bounds","name":"Diagonal Bounds","tags":["power","lateral","single"],"eq":["bw"],"req":[],"tier":2,"dose":"4/s","cues":["Bound forward and across onto one leg","Stick the landing for a beat","Push off and go to the other side"],"steps":["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."],"muscles":["quadriceps","abductors","adductors","calves","glutes","hamstrings"],"img":["img/ex/diagonal-bounds-0.jpg","img/ex/diagonal-bounds-1.jpg"]},{"id":"frog-hops","name":"Frog Hops","tags":["power","squat"],"eq":["bw"],"req":[],"tier":2,"dose":"5","cues":["Wide squat, hands between the feet","Jump forward, land back in the squat","Reset briefly between reps"],"steps":["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/frog-hops-0.jpg","img/ex/frog-hops-1.jpg"]},{"id":"lateral-shuffle","name":"Lateral Shuffle","tags":["cond","lateral","prep"],"eq":["bw"],"req":[],"tier":1,"dose":"20s","cues":["Athletic stance, hips low","Quick small shuffles — don't cross the feet","Change direction every few steps"],"steps":[],"muscles":[],"img":[]},{"id":"shuttle-run","name":"Shuttle Run","tags":["cond","lateral"],"eq":["bw"],"req":[],"tier":1,"dose":"30s","cues":["Two markers about 10m apart","Sprint, touch the line, turn and go","Low hips on the turn"],"steps":[],"muscles":[],"img":[]},{"id":"cable-band-woodchop","name":"Cable / Band Woodchop","tags":["core","power"],"eq":["cable","band"],"req":[],"tier":1,"dose":"8/s","cues":["Anchor high, feet wide","Rotate through the hips and chop down across the body","Arms stay long — power comes from the trunk"],"steps":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"muscles":["abdominals","shoulders"],"img":["img/ex/cable-band-woodchop-0.jpg","img/ex/cable-band-woodchop-1.jpg"]},{"id":"bretzel-stretch","name":"Bretzel Stretch","tags":["stretch","tspine","quads","hips"],"eq":["bw"],"req":[],"tier":2,"dose":"60s/s","cues":["Lie on your side, top knee bent at 90° on the floor","Top hand grabs the bottom ankle behind you","Exhale and let both shoulders drop towards the mat"],"steps":[],"muscles":[],"img":[]},{"id":"frog-stretch","name":"Frog Stretch","tags":["stretch","groin","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"45s","cues":["On all fours, slide the knees wide","Ankles in line with the knees","Rock the hips back gently, breathe"],"steps":[],"muscles":[],"img":[]},{"id":"lizard-stretch","name":"Lizard Stretch","tags":["stretch","hips","groin"],"eq":["bw"],"req":[],"tier":1,"dose":"45s/s","cues":["Long lunge, both hands inside the front foot","Let the hips sink","Drop to the forearms for more"],"steps":[],"muscles":[],"img":[]},{"id":"puppy-pose","name":"Puppy Pose","tags":["stretch","tspine","lats","shoulders"],"eq":["bw"],"req":[],"tier":1,"dose":"45s","cues":["Kneel, walk the hands far forward","Hips over the knees, chest melts to the floor","Breathe into the upper back"],"steps":[],"muscles":[],"img":[]},{"id":"supine-twist","name":"Supine Twist","tags":["stretch","back","tspine","glutes"],"eq":["bw"],"req":[],"tier":1,"dose":"40s/s","cues":["On your back, drop both knees to one side","Arms out, look the other way","Let gravity do the work"],"steps":[],"muscles":[],"img":[]},{"id":"weighted-straddle-fold","name":"Weighted Straddle Fold","tags":["stretch","groin","hams"],"eq":["bw","kb"],"req":[],"tier":1,"dose":"90s","cues":["Sit wide-legged, bell on the floor in front of you","Hold the bell as an anchor and pull the chest forward","Flat back — hinge from the hips, don't round"],"steps":[],"muscles":[],"img":[]},{"id":"crocodile-breathing","name":"Crocodile Breathing","tags":["breath","stretch","back"],"eq":["bw"],"req":[],"tier":1,"dose":"90s","cues":["Lie face down, forehead on your hands","Breathe into your belly so it pushes into the floor","Slow: 4s in, 6s out"],"steps":[],"muscles":[],"img":[]},{"id":"90-90-box-breathing","name":"90/90 Box Breathing","tags":["breath","stretch","back","hips"],"eq":["bw"],"req":[],"tier":1,"dose":"120s","cues":["On your back, feet on a wall or box, knees at 90°","Breathe 4s in, hold 4, 4s out, hold 4","Let the low back and shoulders melt down"],"steps":[],"muscles":[],"img":[]},{"id":"legs-up-the-wall","name":"Legs Up the Wall","tags":["breath","stretch","hams"],"eq":["bw"],"req":[],"tier":1,"dose":"120s","cues":["Lie with your hips near a wall, legs straight up it","Arms relaxed, eyes closed","Long slow exhales — down-regulate"],"steps":[],"muscles":[],"img":[]},{"id":"leg-press","name":"Leg Press","tags":["squat","quads","glutes"],"eq":["machine"],"req":[],"tier":1,"dose":"10","cues":["Feet shoulder-width, mid-platform","Lower until knees reach ~90°, low back stays down","Press through the whole foot, don't lock the knees hard"],"steps":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/leg-press-0.jpg","img/ex/leg-press-1.jpg"]},{"id":"hack-squat","name":"Hack Squat","tags":["squat","quads"],"eq":["machine"],"req":[],"tier":2,"dose":"8","cues":["Shoulders under the pads, feet mid-platform","Sink deep with control","Drive up without the knees caving"],"steps":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/hack-squat-0.jpg","img/ex/hack-squat-1.jpg"]},{"id":"smith-machine-squat","name":"Smith Machine Squat","tags":["squat","quads","glutes"],"eq":["machine"],"req":[],"tier":1,"dose":"8","cues":["Feet slightly in front of the bar","Sit down between the heels","Brace and stand tall"],"steps":["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["quadriceps","calves","glutes","hamstrings","lower back"],"img":["img/ex/smith-machine-squat-0.jpg","img/ex/smith-machine-squat-1.jpg"]},{"id":"leg-extension","name":"Leg Extension","tags":["iso","quads"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Pad on the lower shin, knee lined up with the pivot","Straighten fully and squeeze the quads","Lower slowly — 2–3 seconds"],"steps":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"muscles":["quadriceps"],"img":["img/ex/leg-extension-0.jpg","img/ex/leg-extension-1.jpg"]},{"id":"lying-leg-curl","name":"Lying Leg Curl","tags":["iso","hams"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Hips pressed into the pad","Curl heels to glutes","Slow on the way down"],"steps":["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."],"muscles":["hamstrings"],"img":["img/ex/lying-leg-curl-0.jpg","img/ex/lying-leg-curl-1.jpg"]},{"id":"seated-leg-curl","name":"Seated Leg Curl","tags":["iso","hams"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Thigh pad snug, knee at the pivot","Pull heels under the seat","Control the return"],"steps":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"muscles":["hamstrings"],"img":["img/ex/seated-leg-curl-0.jpg","img/ex/seated-leg-curl-1.jpg"]},{"id":"sumo-deadlift","name":"Sumo Deadlift","tags":["hinge","glutes","groin"],"eq":["bb"],"req":[],"tier":2,"dose":"5","cues":["Wide stance, toes out, hands inside the knees","Push the floor apart, chest up","Hips and shoulders rise together"],"steps":["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"muscles":["hamstrings","adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"img":["img/ex/sumo-deadlift-0.jpg","img/ex/sumo-deadlift-1.jpg"]},{"id":"good-morning","name":"Good Morning","tags":["hinge","hams","back"],"eq":["bb"],"req":[],"tier":2,"dose":"8","cues":["Bar on upper back, soft knees","Push hips back with a flat back","Stop when hamstrings are stretched, stand up"],"steps":["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.","Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.","Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."],"muscles":["hamstrings","abdominals","glutes","lower back"],"img":["img/ex/good-morning-0.jpg","img/ex/good-morning-1.jpg"]},{"id":"walking-lunge","name":"Walking Lunge","tags":["single","squat","glutes"],"eq":["bw","db","kb"],"req":[],"tier":1,"dose":"10/s","cues":["Long step, back knee kisses the floor","Front shin fairly vertical","Drive through the front heel into the next step"],"steps":["Begin standing with your feet shoulder width apart and your hands on your hips.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/walking-lunge-0.jpg","img/ex/walking-lunge-1.jpg"]},{"id":"glute-ham-raise","name":"Glute-Ham Raise","tags":["hinge","hams"],"eq":["machine"],"req":[],"tier":3,"dose":"6","cues":["Knees just behind the pad, feet locked in","Lower with a straight line from knee to head","Curl yourself back up with the hamstrings"],"steps":["Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.","Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.","Return to the starting position, keeping your descent under control."],"muscles":["hamstrings","calves","glutes"],"img":["img/ex/glute-ham-raise-0.jpg","img/ex/glute-ham-raise-1.jpg"]},{"id":"back-extension","name":"Back Extension","tags":["hinge","back","glutes"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Pad at the hip crease","Lower with a flat back","Rise to a straight line — don't over-arch"],"steps":["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.","Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"muscles":["lower back","glutes","hamstrings"],"img":["img/ex/back-extension-0.jpg","img/ex/back-extension-1.jpg"]},{"id":"hip-abduction-machine","name":"Hip Abduction Machine","tags":["iso","glutes","hips"],"eq":["machine"],"req":[],"tier":1,"dose":"15","cues":["Sit tall, lean slightly forward for more glute","Push the knees out","Slow return"],"steps":["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"muscles":["abductors","glutes"],"img":["img/ex/hip-abduction-machine-0.jpg","img/ex/hip-abduction-machine-1.jpg"]},{"id":"hip-adduction-machine","name":"Hip Adduction Machine","tags":["iso","groin"],"eq":["machine"],"req":[],"tier":1,"dose":"15","cues":["Sit tall, pads on the inner knees","Squeeze the legs together","Control the stretch on the way out"],"steps":["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"muscles":["adductors","glutes","hamstrings"],"img":["img/ex/hip-adduction-machine-0.jpg","img/ex/hip-adduction-machine-1.jpg"]},{"id":"cable-glute-kickback","name":"Cable Glute Kickback","tags":["iso","glutes"],"eq":["cable"],"req":[],"tier":1,"dose":"12/s","cues":["Ankle strap on, hold the frame","Kick back and slightly up from the hip","No low-back arching"],"steps":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."],"muscles":["glutes","hamstrings"],"img":["img/ex/cable-glute-kickback-0.jpg","img/ex/cable-glute-kickback-1.jpg"]},{"id":"standing-calf-raise-machine","name":"Standing Calf Raise Machine","tags":["iso","calves","ankles"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Balls of the feet on the edge","Full stretch at the bottom, pause","Rise high onto the big toe"],"steps":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"muscles":["calves"],"img":["img/ex/standing-calf-raise-machine-0.jpg","img/ex/standing-calf-raise-machine-1.jpg"]},{"id":"seated-calf-raise","name":"Seated Calf Raise","tags":["iso","calves"],"eq":["machine"],"req":[],"tier":1,"dose":"15","cues":["Pad on the lower thighs","Deep stretch, pause","Rise up and squeeze"],"steps":["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."],"muscles":["calves"],"img":["img/ex/seated-calf-raise-0.jpg","img/ex/seated-calf-raise-1.jpg"]},{"id":"incline-bench-press","name":"Incline Bench Press","tags":["hpush","chest","shoulders"],"eq":["bb"],"req":["bench"],"tier":2,"dose":"8","cues":["Bench at ~30°, shoulder blades pinned","Lower to the upper chest","Press up and slightly back"],"steps":["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/incline-bench-press-0.jpg","img/ex/incline-bench-press-1.jpg"]},{"id":"incline-dumbbell-press","name":"Incline Dumbbell Press","tags":["hpush","chest","shoulders"],"eq":["db"],"req":["bench"],"tier":1,"dose":"10","cues":["Bench at ~30°","Lower the bells to the sides of the chest","Press up, bells come together"],"steps":["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.","Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.","Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/incline-dumbbell-press-0.jpg","img/ex/incline-dumbbell-press-1.jpg"]},{"id":"chest-press-machine","name":"Chest Press Machine","tags":["hpush","chest"],"eq":["machine"],"req":[],"tier":1,"dose":"10","cues":["Handles at mid-chest height","Press out without shrugging","Slow return to a good stretch"],"steps":["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/chest-press-machine-0.jpg","img/ex/chest-press-machine-1.jpg"]},{"id":"smith-machine-bench-press","name":"Smith Machine Bench Press","tags":["hpush","chest"],"eq":["machine"],"req":["bench"],"tier":1,"dose":"8","cues":["Bar over the lower chest","Elbows ~45° from the body","Press up smoothly"],"steps":["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/smith-machine-bench-press-0.jpg","img/ex/smith-machine-bench-press-1.jpg"]},{"id":"pec-deck","name":"Pec Deck","tags":["iso","chest"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Elbows soft, chest up","Bring the pads together in an arc","Open slowly to a stretch"],"steps":["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."],"muscles":["chest"],"img":["img/ex/pec-deck-0.jpg","img/ex/pec-deck-1.jpg"]},{"id":"cable-fly","name":"Cable Fly","tags":["iso","chest"],"eq":["cable"],"req":[],"tier":1,"dose":"12","cues":["Step forward, slight lean","Hug a big tree — hands meet in front","Control the stretch back"],"steps":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."],"muscles":["chest","shoulders"],"img":["img/ex/cable-fly-0.jpg","img/ex/cable-fly-1.jpg"]},{"id":"dumbbell-fly","name":"Dumbbell Fly","tags":["iso","chest"],"eq":["db"],"req":["bench"],"tier":1,"dose":"12","cues":["Slight bend in the elbows, locked in","Open wide to a chest stretch","Squeeze back together"],"steps":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"muscles":["chest"],"img":["img/ex/dumbbell-fly-0.jpg","img/ex/dumbbell-fly-1.jpg"]},{"id":"dips","name":"Dips","tags":["hpush","chest","triceps"],"eq":["machine","bar"],"req":[],"tier":2,"dose":"8","cues":["Lean slightly forward for chest","Lower until shoulders are just below elbows","Press up to straight arms"],"steps":["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.","While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.","Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.","Repeat the movement for the prescribed amount of repetitions."],"muscles":["chest","shoulders","triceps"],"img":["img/ex/dips-0.jpg","img/ex/dips-1.jpg"]},{"id":"close-grip-pulldown","name":"Close-Grip Pulldown","tags":["vpull","lats"],"eq":["cable"],"req":[],"tier":1,"dose":"10","cues":["Narrow grip, chest up","Pull the handle to the upper chest","Full stretch at the top"],"steps":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."],"muscles":["lats","biceps","middle back","shoulders"],"img":["img/ex/close-grip-pulldown-0.jpg","img/ex/close-grip-pulldown-1.jpg"]},{"id":"straight-arm-pulldown","name":"Straight-Arm Pulldown","tags":["iso","lats"],"eq":["cable"],"req":[],"tier":1,"dose":"12","cues":["Arms long, slight hinge","Sweep the bar to the thighs","Feel the lats, not the triceps"],"steps":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."],"muscles":["lats"],"img":["img/ex/straight-arm-pulldown-0.jpg","img/ex/straight-arm-pulldown-1.jpg"]},{"id":"t-bar-row","name":"T-Bar Row","tags":["hpull","back","lats"],"eq":["bb"],"req":[],"tier":2,"dose":"8","cues":["Hinge to ~45°, flat back","Row the handle to the chest","Lower under control"],"steps":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"muscles":["middle back","biceps","lats"],"img":["img/ex/t-bar-row-0.jpg","img/ex/t-bar-row-1.jpg"]},{"id":"machine-row","name":"Machine Row","tags":["hpull","back"],"eq":["machine"],"req":[],"tier":1,"dose":"10","cues":["Chest on the pad","Pull elbows back, squeeze the shoulder blades","Slow return"],"steps":["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"muscles":["lats","biceps","middle back"],"img":["img/ex/machine-row-0.jpg","img/ex/machine-row-1.jpg"]},{"id":"high-row-machine","name":"High Row Machine","tags":["vpull","hpull","lats","back"],"eq":["machine"],"req":[],"tier":1,"dose":"10","cues":["Sit tall, chest on the pad","Drive the elbows down and back","Control the stretch up"],"steps":["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position.","For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"muscles":["middle back","lats"],"img":["img/ex/high-row-machine-0.jpg","img/ex/high-row-machine-1.jpg"]},{"id":"chest-supported-incline-row","name":"Chest-Supported Incline Row","tags":["hpull","back"],"eq":["db"],"req":["bench"],"tier":1,"dose":"10","cues":["Chest on an incline bench","Row both bells to the hips","Pause and squeeze"],"steps":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"muscles":["middle back","biceps","forearms","lats","shoulders"],"img":["img/ex/chest-supported-incline-row-0.jpg","img/ex/chest-supported-incline-row-1.jpg"]},{"id":"weighted-pull-up","name":"Weighted Pull-Up","tags":["vpull","lats"],"eq":["bar"],"req":[],"tier":3,"dose":"5","cues":["Belt or bell between the knees","Full hang to chin over bar","No kipping"],"steps":["Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.","You'll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.","Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.","After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched."],"muscles":["lats","biceps","middle back"],"img":["img/ex/weighted-pull-up-0.jpg","img/ex/weighted-pull-up-1.jpg"]},{"id":"shoulder-press-machine","name":"Shoulder Press Machine","tags":["vpush","shoulders"],"eq":["machine"],"req":[],"tier":1,"dose":"10","cues":["Handles at shoulder height","Press overhead without arching","Lower to the start"],"steps":["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"muscles":["shoulders","triceps"],"img":["img/ex/shoulder-press-machine-0.jpg","img/ex/shoulder-press-machine-1.jpg"]},{"id":"arnold-press","name":"Arnold Press","tags":["vpush","shoulders"],"eq":["db"],"req":[],"tier":2,"dose":"10","cues":["Start palms facing you at the chin","Rotate out as you press up","Reverse on the way down"],"steps":["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.","Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.","Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"muscles":["shoulders","triceps"],"img":["img/ex/arnold-press-0.jpg","img/ex/arnold-press-1.jpg"]},{"id":"lateral-raise","name":"Lateral Raise","tags":["iso","shoulders"],"eq":["db","cable","band"],"req":[],"tier":1,"dose":"12","cues":["Slight lean forward, soft elbows","Raise out to shoulder height, lead with the elbows","Lower slowly"],"steps":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"muscles":["shoulders"],"img":["img/ex/lateral-raise-0.jpg","img/ex/lateral-raise-1.jpg"]},{"id":"front-raise","name":"Front Raise","tags":["iso","shoulders"],"eq":["db","kb","band"],"req":[],"tier":1,"dose":"12","cues":["Arms nearly straight","Raise to eye level","No swinging"],"steps":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."],"muscles":["shoulders"],"img":["img/ex/front-raise-0.jpg","img/ex/front-raise-1.jpg"]},{"id":"rear-delt-fly","name":"Rear Delt Fly","tags":["iso","prehab","shoulders","back"],"eq":["machine","db","cable"],"req":[],"tier":1,"dose":"15","cues":["Face the pad, arms long","Sweep the arms back in an arc","Squeeze the rear shoulders"],"steps":["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."],"muscles":["shoulders"],"img":["img/ex/rear-delt-fly-0.jpg","img/ex/rear-delt-fly-1.jpg"]},{"id":"upright-row","name":"Upright Row","tags":["iso","shoulders"],"eq":["bb","db","cable"],"req":[],"tier":2,"dose":"10","cues":["Hands shoulder-width or wider","Pull elbows up to shoulder height — no higher","Stop if the shoulders pinch"],"steps":["Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.","Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"muscles":["shoulders","traps"],"img":["img/ex/upright-row-0.jpg","img/ex/upright-row-1.jpg"]},{"id":"shrugs","name":"Shrugs","tags":["iso","back","shoulders"],"eq":["db","bb"],"req":[],"tier":1,"dose":"12","cues":["Arms long, stand tall","Shrug straight up to the ears","Pause, lower slowly"],"steps":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."],"muscles":["traps"],"img":["img/ex/shrugs-0.jpg","img/ex/shrugs-1.jpg"]},{"id":"barbell-curl","name":"Barbell Curl","tags":["arms","iso","biceps"],"eq":["bb"],"req":[],"tier":1,"dose":"10","cues":["Elbows pinned to the sides","Curl without swinging","Lower all the way down"],"steps":["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"muscles":["biceps","forearms"],"img":["img/ex/barbell-curl-0.jpg","img/ex/barbell-curl-1.jpg"]},{"id":"dumbbell-curl","name":"Dumbbell Curl","tags":["arms","iso","biceps"],"eq":["db","kb"],"req":[],"tier":1,"dose":"10","cues":["Palms forward, elbows still","Curl and squeeze at the top","Slow negative"],"steps":["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["biceps","forearms"],"img":["img/ex/dumbbell-curl-0.jpg","img/ex/dumbbell-curl-1.jpg"]},{"id":"hammer-curl","name":"Hammer Curl","tags":["arms","iso","biceps"],"eq":["db","kb"],"req":[],"tier":1,"dose":"10","cues":["Palms facing each other","Curl without swinging","Control down"],"steps":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["biceps"],"img":["img/ex/hammer-curl-0.jpg","img/ex/hammer-curl-1.jpg"]},{"id":"preacher-curl","name":"Preacher Curl","tags":["arms","iso","biceps"],"eq":["bb","db","machine"],"req":["bench"],"tier":1,"dose":"10","cues":["Armpits snug on the pad","Curl up, don't lift the elbows","Lower to nearly straight"],"steps":["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."],"muscles":["biceps"],"img":["img/ex/preacher-curl-0.jpg","img/ex/preacher-curl-1.jpg"]},{"id":"cable-curl","name":"Cable Curl","tags":["arms","iso","biceps"],"eq":["cable","band"],"req":[],"tier":1,"dose":"12","cues":["Elbows at your sides","Curl the bar up","Constant tension — slow down"],"steps":["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the curl bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"muscles":["biceps"],"img":["img/ex/cable-curl-0.jpg","img/ex/cable-curl-1.jpg"]},{"id":"concentration-curl","name":"Concentration Curl","tags":["arms","iso","biceps"],"eq":["db"],"req":[],"tier":1,"dose":"10/s","cues":["Elbow braced on the inner thigh","Curl to the shoulder, squeeze","Slow lower"],"steps":["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."],"muscles":["biceps","forearms"],"img":["img/ex/concentration-curl-0.jpg","img/ex/concentration-curl-1.jpg"]},{"id":"triceps-pushdown","name":"Triceps Pushdown","tags":["arms","iso","triceps"],"eq":["cable","band"],"req":[],"tier":1,"dose":"12","cues":["Elbows pinned at your sides","Push down and spread the rope at the bottom","Let it rise to 90° only"],"steps":["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"muscles":["triceps"],"img":["img/ex/triceps-pushdown-0.jpg","img/ex/triceps-pushdown-1.jpg"]},{"id":"overhead-triceps-extension","name":"Overhead Triceps Extension","tags":["arms","iso","triceps"],"eq":["cable","db","band"],"req":[],"tier":1,"dose":"12","cues":["Face away, rope behind the head","Extend the arms forward and up","Feel the stretch on the way back"],"steps":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."],"muscles":["triceps"],"img":["img/ex/overhead-triceps-extension-0.jpg","img/ex/overhead-triceps-extension-1.jpg"]},{"id":"skull-crusher","name":"Skull Crusher","tags":["arms","iso","triceps"],"eq":["bb","db"],"req":["bench"],"tier":2,"dose":"10","cues":["Upper arms vertical","Lower to the forehead, elbows in","Extend to straight arms"],"steps":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."],"muscles":["triceps","forearms"],"img":["img/ex/skull-crusher-0.jpg","img/ex/skull-crusher-1.jpg"]},{"id":"close-grip-bench-press","name":"Close-Grip Bench Press","tags":["hpush","arms","triceps","chest"],"eq":["bb"],"req":["bench"],"tier":2,"dose":"8","cues":["Hands shoulder-width","Elbows tucked as you lower","Press up with the triceps"],"steps":["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"muscles":["triceps","chest","shoulders"],"img":["img/ex/close-grip-bench-press-0.jpg","img/ex/close-grip-bench-press-1.jpg"]},{"id":"bench-dips","name":"Bench Dips","tags":["arms","triceps"],"eq":["bw"],"req":["bench"],"tier":1,"dose":"12","cues":["Hands on a bench behind you","Lower until elbows are ~90°","Press back up"],"steps":["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."],"muscles":["triceps","chest","shoulders"],"img":["img/ex/bench-dips-0.jpg","img/ex/bench-dips-1.jpg"]},{"id":"cable-crunch","name":"Cable Crunch","tags":["core"],"eq":["cable"],"req":[],"tier":1,"dose":"12","cues":["Kneel, rope by the head","Curl the ribs to the hips","Hips stay still"],"steps":["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."],"muscles":["abdominals"],"img":["img/ex/cable-crunch-0.jpg","img/ex/cable-crunch-1.jpg"]},{"id":"ab-crunch-machine","name":"Ab Crunch Machine","tags":["core"],"eq":["machine"],"req":[],"tier":1,"dose":"12","cues":["Set the seat so the pads sit on your chest","Crunch down with the abs","Slow return"],"steps":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."],"muscles":["abdominals"],"img":["img/ex/ab-crunch-machine-0.jpg","img/ex/ab-crunch-machine-1.jpg"]},{"id":"incline-treadmill-walk","name":"Incline Treadmill Walk","tags":["cond"],"eq":["cardio"],"req":[],"tier":1,"dose":"600s","cues":["Incline 8–12%, brisk pace","Don't hold the rails","Conversational effort"],"steps":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn't burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/incline-treadmill-walk-0.jpg","img/ex/incline-treadmill-walk-1.jpg"]},{"id":"stair-climber","name":"Stair Climber","tags":["cond"],"eq":["cardio"],"req":[],"tier":1,"dose":"300s","cues":["Steady pace, stand tall","Light hands on the rails","Whole foot on each step"],"steps":["To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.","Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don't fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/stair-climber-0.jpg","img/ex/stair-climber-1.jpg"]},{"id":"elliptical","name":"Elliptical","tags":["cond"],"eq":["cardio"],"req":[],"tier":1,"dose":"600s","cues":["Smooth strides, push and pull the handles","Moderate resistance","Easy on the joints"],"steps":["To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/elliptical-0.jpg","img/ex/elliptical-1.jpg"]},{"id":"stationary-bike","name":"Stationary Bike","tags":["cond"],"eq":["cardio"],"req":[],"tier":1,"dose":"600s","cues":["Seat at hip height","Steady cadence 80–90 rpm","Add intervals for conditioning"],"steps":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."],"muscles":["quadriceps","calves","glutes","hamstrings"],"img":["img/ex/stationary-bike-0.jpg","img/ex/stationary-bike-1.jpg"]},{"id":"calf-raise","name":"Calf Raise","tags":["prehab","calves","ankles"],"eq":["bw","db","kb"],"req":[],"tier":1,"dose":"15","cues":["Rise up onto the big toe","Pause at the top, slow lower","Do them on a step for more range"],"steps":["Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.","With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.","As you inhale, go back to the starting position by slowly lowering the heels.","Repeat for the recommended amount of times."],"muscles":["calves"],"img":["img/ex/calf-raise-0.jpg","img/ex/calf-raise-1.jpg"]}];
